insert into public.experiment_publications(slug,data,status) values ('red-cabbage-ph-indicator','{"id":"exp-01","slug":"red-cabbage-ph-indicator","topicId":"acids-bases","durationSeconds":260,"safetyLevel":"student_lab","featured":true,"youtubeVideo":"https://www.youtube.com/watch?v=I18K2upEHLc","chemicalEquation":"HIn (aq, red, pH < 3) ⇌ H⁺ (aq) + In⁻ (aq, blue/green, pH > 8)","illustration":"indicator-flask","title":{"en":"Red Cabbage pH Experiment","ky":"Кызыл кочан pH-индикатору","ru":"Шкала pH из красной капусты"},"shortDescription":{"en":"See how anthocyanin pigments shift from ruby red in acids to violet, blue, and emerald green in bases.","ky":"Антоцианин пигменттери кислотада кызылдан негизде көк жана жашыл өңгө кантип өтөрүн байкаңыз.","ru":"Наблюдайте, как антоцианы меняют окраску от рубиново-красной в кислотах до синей и изумрудной в щелочах."},"objectives":{"en":["Explain how anthocyanin molecules change structure across the pH scale (pH 1–13).","Distinguish acidic, neutral, and alkaline solutions visually using a natural indicator.","Relate color transitions to hydrogen ion concentration [H⁺]."],"ky":["Антоцианин молекулаларынын pH 1–13 шкаласында өңүн өзгөртүү себебин түшүндүрүү.","Кислоталуу, нейтралдуу жана щелочтуу эритмелерди табигый индикатор менен айырмалоо.","Өңдүн өзгөрүшүн суутек иондорунун [H⁺] концентрациясы менен байланыштыруу."],"ru":["Объяснить изменение структуры молекул антоцианов в диапазоне pH 1–13.","Различать кислую, нейтральную и щелочную среду с помощью природного индикатора.","Связать изменение окраски с концентрацией ионов водорода [H⁺]."]},"materials":{"en":["Aqueous red cabbage extract","6 test tubes in a rack","Dilute HCl (0.1 M)","Vinegar (CH₃COOH)","Distilled water","Sodium bicarbonate (NaHCO₃)","Dilute NaOH (0.1 M)","Safety goggles & gloves"],"ky":["Кызыл кочандын суудагы экстракты","Штативдеги 6 пробирка","Суюлтулган HCl (0.1 М)","Уксус кислотасы (CH₃COOH)","Дистилденген суу","Аш содасы (NaHCO₃)","Суюлтулган NaOH (0.1 М)","Коргоочу көз айнек жана кол кап"],"ru":["Водный экстракт краснокочанной капусты","Штатив с 6 пробирками","Разбавленная HCl (0,1 М)","Уксусная кислота (CH₃COOH)","Дистиллированная вода","Гидрокарбонат натрия (NaHCO₃)","Разбавленный NaOH (0,1 М)","Защитные очки и перчатки"]},"safetyNotes":{"en":["Wear splash-proof safety goggles and nitrile gloves when handling dilute hydrochloric acid (HCl) and sodium hydroxide (NaOH).","Sodium hydroxide is corrosive to skin and eyes; rinse immediately with plenty of water if contact occurs."],"ky":["Суюлтулган туз кислотасы (HCl) жана натрий гидроксиди (NaOH) менен иштегенде сөзсүз коргоочу көз айнек жана кол кап кийиңиз.","Щелочь териге тийсе, дароо көп өлчөмдөгү агын суу менен жууңуз."],"ru":["Используйте защитные очки и перчатки при работе с разбавленными растворами соляной кислоты (HCl) и гидроксида натрия (NaOH).","Щёлочи едки для кожи и глаз — при попадании немедленно промойте большим количеством воды."]},"scientificExplanation":{"en":["Red cabbage leaves contain water-soluble flavylium pigments called anthocyanins. Unlike litmus or phenolphthalein which only show two colors, anthocyanins undergo multiple reversible proton-transfer steps.","In strongly acidic solutions (pH < 3), the fully protonated flavylium cation dominates and absorbs light to appear bright red. Around neutral pH 7, a quinoidal base form appears violet. In alkaline conditions (pH 8–11), anionic forms turn blue and bluish-green, while in strong alkali (pH > 12) chalcone formation yields a yellow solution."],"ky":["Кызыл кочандын жалбырактарында сууда эрүүчү антоцианин пигменттери бар. Ал протонду кошуп алуу же берүү аркылуу бир нече баскычтуу кайтарымдуу реакцияга кирет.","Күчтүү кислотада (pH < 3) флавилий катиону кызыл өң берет. Нейтралдуу чөйрөдө (pH 7) кызгылт-көк, щелочтуу чөйрөдө (pH 8–11) көк жана жашыл, ал эми күчтүү щелочто (pH > 12) сары өң пайда болот."],"ru":["Листья краснокочанной капусты содержат водорастворимые пигменты — антоцианы. В отличие от фенолфталеина, они способны последовательно отдавать несколько протонов (H⁺), образуя формы с разной длиной сопряжённых связей.","В сильнокислой среде (pH < 3) преобладает красный катион флавилия. В нейтральной среде (pH 7) раствор фиолетовый, в слабощелочной (pH 8–11) — синий и изумрудно-зелёный, а в сильнощелочной (pH > 12) переходит в жёлтый халкон."]},"steps":[{"timeSeconds":12,"title":{"en":"Extract preparation","ky":"Экстрактты даярдоо","ru":"Приготовление экстракта"},"detail":{"en":"Warm chopped red cabbage in distilled water and filter to obtain a deep violet stock indicator (pH ~7).","ky":"Тууралган кызыл кочанды жылуу дистилденген сууга салып, чыпкалап кочкул сыя өңдөгү экстракт алабыз.","ru":"Настаиваем измельчённую капусту в тёплой дистиллированной воде и фильтруем фиолетовый раствор (pH ~7)."}},{"timeSeconds":65,"title":{"en":"Acidic tubes (pH 1–4)","ky":"Кислоталуу пробиркалар (pH 1–4)","ru":"Кислая среда (pH 1–4)"},"detail":{"en":"Adding dilute HCl and vinegar immediately turns the violet solution crimson and rose-pink.","ky":"Суюлтулган HCl жана уксус кошулганда эритме дароо ачык кызыл жана кызгылт өңгө өтөт.","ru":"При добавлении HCl и уксусной кислоты раствор мгновенно становится ярко-красным и розовым."}},{"timeSeconds":140,"title":{"en":"Alkaline tubes (pH 8–13)","ky":"Щелочтуу пробиркалар (pH 8–13)","ru":"Щелочная среда (pH 8–13)"},"detail":{"en":"Adding sodium bicarbonate and dilute NaOH shifts the indicator through royal blue to emerald green and gold.","ky":"Аш содасы жана NaOH кошулганда индикатор көк, зумруд жашыл жана сары өңгө өзгөрөт.","ru":"Гидрокарбонат и гидроксид натрия переводят окраску в синюю, изумрудно-зелёную и жёлтую."}}],"quiz":[{"id":"q1","prompt":{"en":"What color does red cabbage anthocyanin indicator turn when added to a weakly alkaline baking soda (NaHCO₃, pH ~8.5) solution?","ky":"Кызыл кочандын антоцианин индикаторун аш содасынын (NaHCO₃, pH ~8.5) начар щелочтуу эритмесине кошкондо кандай өңгө өтөт?","ru":"Какую окраску принимает антоциановый индикатор при добавлении в слабощелочной раствор питьевой соды (NaHCO₃, pH ~8,5)?"},"conceptTag":"acids-bases","options":[{"id":"a","text":{"en":"Bright ruby red","ky":"Ачык кызыл","ru":"Ярко-красную"}},{"id":"b","text":{"en":"Blue to teal-green","ky":"Көк же көгүш-жашыл","ru":"Синюю / сине-зелёную"}},{"id":"c","text":{"en":"Colorless precipitate","ky":"Түссүз чөкмө","ru":"Бесцветный осадок"}}]},{"id":"q2","prompt":{"en":"Why can red cabbage extract distinguish more pH regions than phenolphthalein?","ky":"Эмне үчүн кызыл кочандын экстракты фенолфталеинге караганда pH шкаласынын көбүрөөк бөлүгүн айырмалай алат?","ru":"Почему экстракт краснокочанной капусты позволяет различить больше областей pH, чем фенолфталеин?"},"conceptTag":"acids-bases","options":[{"id":"a","text":{"en":"It undergoes multiple reversible protonation equilibria, forming several distinctly colored molecular species.","ky":"Ал бир нече баскычтуу кайтарымдуу протон алмашууга кирип, ар кандай өңдөгү формаларды пайда кылат.","ru":"Он вступает в несколько ступеней протолитического равновесия, образуя ряд разноокрашенных форм."}},{"id":"b","text":{"en":"It boils at a lower temperature than synthetic indicators.","ky":"Ал синтетикалык индикаторлорго караганда төмөн температурада кайнайт.","ru":"Он кипит при более низкой температуре, чем синтетические индикаторы."}}]}],"transcriptSegments":[{"id":"exp-01-seg-1","startSeconds":0,"endSeconds":65,"text":{"en":"[Stage 1: Extract preparation] Warm chopped red cabbage in distilled water and filter to obtain a deep violet stock indicator (pH ~7). Scientific context: Red cabbage leaves contain water-soluble flavylium pigments called anthocyanins. Unlike litmus or phenolphthalein which only show two colors, anthocyanins undergo multiple reversible proton-transfer steps.","ky":"[1-баскыч: Экстрактты даярдоо] Тууралган кызыл кочанды жылуу дистилденген сууга салып, чыпкалап кочкул сыя өңдөгү экстракт алабыз. Илимий түшүндүрмө: Кызыл кочандын жалбырактарында сууда эрүүчү антоцианин пигменттери бар. Ал протонду кошуп алуу же берүү аркылуу бир нече баскычтуу кайтарымдуу реакцияга кирет.","ru":"[Этап 1: Приготовление экстракта] Настаиваем измельчённую капусту в тёплой дистиллированной воде и фильтруем фиолетовый раствор (pH ~7). Научное объяснение: Листья краснокочанной капусты содержат водорастворимые пигменты — антоцианы. В отличие от фенолфталеина, они способны последовательно отдавать несколько протонов (H⁺), образуя формы с разной длиной сопряжённых связей."}},{"id":"exp-01-seg-2","startSeconds":65,"endSeconds":140,"text":{"en":"[Stage 2: Acidic tubes (pH 1–4)] Adding dilute HCl and vinegar immediately turns the violet solution crimson and rose-pink. Scientific context: In strongly acidic solutions (pH < 3), the fully protonated flavylium cation dominates and absorbs light to appear bright red. Around neutral pH 7, a quinoidal base form appears violet. In alkaline conditions (pH 8–11), anionic forms turn blue and bluish-green, while in strong alkali (pH > 12) chalcone formation yields a yellow solution.","ky":"[2-баскыч: Кислоталуу пробиркалар (pH 1–4)] Суюлтулган HCl жана уксус кошулганда эритме дароо ачык кызыл жана кызгылт өңгө өтөт. Илимий түшүндүрмө: Күчтүү кислотада (pH < 3) флавилий катиону кызыл өң берет. Нейтралдуу чөйрөдө (pH 7) кызгылт-көк, щелочтуу чөйрөдө (pH 8–11) көк жана жашыл, ал эми күчтүү щелочто (pH > 12) сары өң пайда болот.","ru":"[Этап 2: Кислая среда (pH 1–4)] При добавлении HCl и уксусной кислоты раствор мгновенно становится ярко-красным и розовым. Научное объяснение: В сильнокислой среде (pH < 3) преобладает красный катион флавилия. В нейтральной среде (pH 7) раствор фиолетовый, в слабощелочной (pH 8–11) — синий и изумрудно-зелёный, а в сильнощелочной (pH > 12) переходит в жёлтый халкон."}},{"id":"exp-01-seg-3","startSeconds":140,"endSeconds":260,"text":{"en":"[Stage 3: Alkaline tubes (pH 8–13)] Adding sodium bicarbonate and dilute NaOH shifts the indicator through royal blue to emerald green and gold. Scientific context: In strongly acidic solutions (pH < 3), the fully protonated flavylium cation dominates and absorbs light to appear bright red. Around neutral pH 7, a quinoidal base form appears violet. In alkaline conditions (pH 8–11), anionic forms turn blue and bluish-green, while in strong alkali (pH > 12) chalcone formation yields a yellow solution.","ky":"[3-баскыч: Щелочтуу пробиркалар (pH 8–13)] Аш содасы жана NaOH кошулганда индикатор көк, зумруд жашыл жана сары өңгө өзгөрөт. Илимий түшүндүрмө: Күчтүү кислотада (pH < 3) флавилий катиону кызыл өң берет. Нейтралдуу чөйрөдө (pH 7) кызгылт-көк, щелочтуу чөйрөдө (pH 8–11) көк жана жашыл, ал эми күчтүү щелочто (pH > 12) сары өң пайда болот.","ru":"[Этап 3: Щелочная среда (pH 8–13)] Гидрокарбонат и гидроксид натрия переводят окраску в синюю, изумрудно-зелёную и жёлтую. Научное объяснение: В сильнокислой среде (pH < 3) преобладает красный катион флавилия. В нейтральной среде (pH 7) раствор фиолетовый, в слабощелочной (pH 8–11) — синий и изумрудно-зелёный, а в сильнощелочной (pH > 12) переходит в жёлтый халкон."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('catalytic-decomposition-hydrogen-peroxide','{"id":"exp-02","slug":"catalytic-decomposition-hydrogen-peroxide","topicId":"reactions","durationSeconds":215,"safetyLevel":"teacher_demo","featured":true,"youtubeVideo":"https://www.youtube.com/watch?v=p1eG2y2mn54","chemicalEquation":"2H₂O₂ (aq) —[KI / MnO₂]→ 2H₂O (l) + O₂ (g) + ΔH","illustration":"peroxide-foam","title":{"en":"Hydrogen Peroxide Catalysis","ky":"Пероксиддин каталитикалык ажыроосу","ru":"Каталитическое разложение H₂O₂"},"shortDescription":{"en":"Watch iodide ions dramatically accelerate H₂O₂ decomposition, trapping oxygen gas in a rising column of warm foam.","ky":"Иодид иондору H₂O₂ ажыроосун кантип ылдамдатып, кычкылтек газын жылуу көбүккө айлантарын көрүңүз.","ru":"Увидьте, как ионы иодида ускоряют разложение H₂O₂ в тысячи раз, превращая выделяющийся кислород в столб тёплой пены."},"objectives":{"en":["Define the role of a catalyst in lowering activation energy (Eₐ) without being consumed.","Identify the gas trapped inside the foam bubbles as molecular oxygen (O₂).","Explain why steam rises from the foam (exothermic reaction, ΔH < 0)."],"ky":["Катализатордун активдешүү энергиясын (Eₐ) төмөндөтүү ролун түшүндүрүү.","Көбүктүн ичиндеги газ кычкылтек (O₂) экенин аныктоо.","Реакция эмне үчүн жылуулук бөлүп чыгаруу менен (экзотермиялык, ΔH < 0) жүрөрүн түшүнүү."],"ru":["Объяснить роль катализатора в снижении энергии активации (Eₐ).","Определить, что пена наполнена выделяющимся газообразным кислородом (O₂).","Объяснить выделение пара экзотермическим характером реакции (ΔH < 0)."]},"materials":{"en":["Hydrogen peroxide H₂O₂ (6–12% teacher demo grade)","Potassium iodide (KI) solution (2 M)","Liquid dish soap","500 mL graduated cylinder & catch tray","Glowing wooden splint","Goggles, lab coat & thermal gloves"],"ky":["Суутек пероксиди H₂O₂ (6–12%)","Калий иодидинин (KI) эритмеси (2 М)","Суюк самын","500 мл өлчөөчү цилиндр жана табакча","Чок болуп турган чырпык","Коргоочу көз айнек, халат жана кол кап"],"ru":["Пероксид водорода H₂O₂ (6–12%)","Раствор иодида калия KI (2 М)","Жидкое мыло","Мерный цилиндр на 500 мл и поддон","Тлеющая лучинка","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Teacher demonstration only when using >3% H₂O₂. Concentrated hydrogen peroxide is a strong oxidizer that causes skin burns.","The reaction is strongly exothermic — the foam and cylinder become hot (>75 °C). Do not touch freshly formed foam with bare hands."],"ky":["3% жогору H₂O₂ колдонулганда тажрыйбаны мугалим гана көрсөтөт. Концентрацияланган пероксид терини күйгүзөт.","Реакция экзотермиялык болгондуктан көбүк абдан ысык болот (>75 °C) — колуңуз менен кармабаңыз."],"ru":["Демонстрация проводится только учителем. Концентрированный H₂O₂ вызывает ожоги кожи и слизистых.","Реакция сильно экзотермична (>75 °C) — не прикасайтесь к свежей пене без перчаток."]},"scientificExplanation":{"en":["On its own at room temperature, hydrogen peroxide decomposes into water and oxygen very slowly because the uncatalyzed O–O bond cleavage has a high activation energy (~75 kJ/mol).","When iodide ions (I⁻) are added, they provide an alternative two-step pathway via hypoiodite (IO⁻) with a much lower activation energy: Step 1: H₂O₂ + I⁻ → H₂O + IO⁻; Step 2: H₂O₂ + IO⁻ → H₂O + O₂ (g) + I⁻. Notice that I⁻ is regenerated in Step 2, acting as a true catalyst while releasing ~196 kJ of heat per 2 moles of H₂O₂."],"ky":["Бөлмө температурасында суутек пероксиди өз алдынча өтө жай ажырайт, анткени активдешүү энергиясы жогору (~75 кДж/моль).","Иодид иондору (I⁻) кошулганда реакция эки баскычтуу жеңил жол менен жүрөт: 1) H₂O₂ + I⁻ → H₂O + IO⁻; 2) H₂O₂ + IO⁻ → H₂O + O₂↑ + I⁻. Натыйжада I⁻ кайра калыбына келет, ал эми бөлүнүп чыккан кычкылтек самынды көбүртөт."],"ru":["Без катализатора пероксид водорода разлагается крайне медленно из-за высокой энергии активации (~75 кДж/моль).","Иодид-ионы (I⁻) открывают двухстадийный путь через гипоиодит-ион (IO⁻) с низкой энергией активации: 1) H₂O₂ + I⁻ → H₂O + IO⁻; 2) H₂O₂ + IO⁻ → H₂O + O₂↑ + I⁻. Катализатор I⁻ регенерируется, а бурно выделяющийся кислород вспенивает мыльный раствор с выделением тепла."]},"steps":[{"timeSeconds":18,"title":{"en":"Mix peroxide & surfactant","ky":"Пероксид менен самынды аралаштыруу","ru":"Смешивание пероксида и ПАВ"},"detail":{"en":"Pour H₂O₂ into the cylinder and swirl with dish soap so any evolved gas will be captured as foam.","ky":"Цилиндрге H₂O₂ куюп, бөлүнүп чыгуучу газды кармап калуу үчүн суюк самын кошобуз.","ru":"Наливаем H₂O₂ в цилиндр и добавляем жидкое мыло для улавливания пузырьков газа."}},{"timeSeconds":58,"title":{"en":"Add KI catalyst","ky":"KI катализаторун кошуу","ru":"Введение катализатора KI"},"detail":{"en":"Pouring aqueous potassium iodide triggers immediate vigorous foaming and visible water vapor.","ky":"Калий иодидин куйганда көбүк дароо көтөрүлүп, жылуу буу чыгат.","ru":"При добавлении раствора KI мгновенно вырастает столб горячей пены и поднимается пар."}},{"timeSeconds":135,"title":{"en":"Glowing splint oxygen test","ky":"Кычкылтекти чырпык менен текшерүү","ru":"Проверка кислорода тлеющей лучинкой"},"detail":{"en":"Touching a glowing splint to the foam causes it to relight into flame, proving the gas is O₂.","ky":"Чок болуп турган чырпыкты көбүккө тийгизгенде ал кайра жанат — бул O₂ газынын далили.","ru":"Тлеющая лучинка ярко вспыхивает в пене, доказывая, что пузырьки заполнены чистым O₂."}}],"quiz":[{"id":"q1","prompt":{"en":"What happens to the iodide ions (I⁻) after the decomposition of H₂O₂ is complete?","ky":"H₂O₂ ажырап бүткөндөн кийин иодид иондоруна (I⁻) эмне болот?","ru":"Что происходит с иодид-ионами (I⁻) после завершения разложения H₂O₂?"},"conceptTag":"reactions","options":[{"id":"a","text":{"en":"They are regenerated in the second reaction step, remaining chemically unchanged overall (with minor side oxidation to I₂).","ky":"Алар экинчи баскычта кайра калыбына келет, б.а. катализатор катары сарпталбайт.","ru":"Они регенерируются на второй стадии механизма, выступая катализатором."}},{"id":"b","text":{"en":"They turn into oxygen gas molecules.","ky":"Алар кычкылтек газынын молекуласына айланат.","ru":"Они превращаются в молекулы газообразного кислорода."}}]},{"id":"q2","prompt":{"en":"Why does visible steam rise from the foam column during this experiment?","ky":"Эмне үчүн бул тажрыйба учурунда көбүктөн буу көтөрүлөт?","ru":"Почему над столбом пены в этом опыте поднимается заметный пар?"},"conceptTag":"reactions","options":[{"id":"a","text":{"en":"The decomposition of H₂O₂ into H₂O and O₂ is strongly exothermic (ΔH = −196 kJ per 2 mol H₂O₂), heating the water into vapor.","ky":"H₂O₂ ажыроосу экзотермиялык реакция болгондуктан (ΔH < 0), бөлүнүп чыккан жылуулук сууну буулантат.","ru":"Разложение H₂O₂ сильно экзотермично (ΔH < 0), и выделяющаяся теплота испаряет часть воды."}},{"id":"b","text":{"en":"Dish soap reacts endothermically with glass.","ky":"Суюк самын айнек менен эндотермиялык реакцияга кирет.","ru":"Мыло вступает в эндотермическую реакцию со стеклом."}}]}],"transcriptSegments":[{"id":"exp-02-seg-1","startSeconds":0,"endSeconds":58,"text":{"en":"[Stage 1: Mix peroxide & surfactant] Pour H₂O₂ into the cylinder and swirl with dish soap so any evolved gas will be captured as foam. Scientific context: On its own at room temperature, hydrogen peroxide decomposes into water and oxygen very slowly because the uncatalyzed O–O bond cleavage has a high activation energy (~75 kJ/mol).","ky":"[1-баскыч: Пероксид менен самынды аралаштыруу] Цилиндрге H₂O₂ куюп, бөлүнүп чыгуучу газды кармап калуу үчүн суюк самын кошобуз. Илимий түшүндүрмө: Бөлмө температурасында суутек пероксиди өз алдынча өтө жай ажырайт, анткени активдешүү энергиясы жогору (~75 кДж/моль).","ru":"[Этап 1: Смешивание пероксида и ПАВ] Наливаем H₂O₂ в цилиндр и добавляем жидкое мыло для улавливания пузырьков газа. Научное объяснение: Без катализатора пероксид водорода разлагается крайне медленно из-за высокой энергии активации (~75 кДж/моль)."}},{"id":"exp-02-seg-2","startSeconds":58,"endSeconds":135,"text":{"en":"[Stage 2: Add KI catalyst] Pouring aqueous potassium iodide triggers immediate vigorous foaming and visible water vapor. Scientific context: When iodide ions (I⁻) are added, they provide an alternative two-step pathway via hypoiodite (IO⁻) with a much lower activation energy: Step 1: H₂O₂ + I⁻ → H₂O + IO⁻; Step 2: H₂O₂ + IO⁻ → H₂O + O₂ (g) + I⁻. Notice that I⁻ is regenerated in Step 2, acting as a true catalyst while releasing ~196 kJ of heat per 2 moles of H₂O₂.","ky":"[2-баскыч: KI катализаторун кошуу] Калий иодидин куйганда көбүк дароо көтөрүлүп, жылуу буу чыгат. Илимий түшүндүрмө: Иодид иондору (I⁻) кошулганда реакция эки баскычтуу жеңил жол менен жүрөт: 1) H₂O₂ + I⁻ → H₂O + IO⁻; 2) H₂O₂ + IO⁻ → H₂O + O₂↑ + I⁻. Натыйжада I⁻ кайра калыбына келет, ал эми бөлүнүп чыккан кычкылтек самынды көбүртөт.","ru":"[Этап 2: Введение катализатора KI] При добавлении раствора KI мгновенно вырастает столб горячей пены и поднимается пар. Научное объяснение: Иодид-ионы (I⁻) открывают двухстадийный путь через гипоиодит-ион (IO⁻) с низкой энергией активации: 1) H₂O₂ + I⁻ → H₂O + IO⁻; 2) H₂O₂ + IO⁻ → H₂O + O₂↑ + I⁻. Катализатор I⁻ регенерируется, а бурно выделяющийся кислород вспенивает мыльный раствор с выделением тепла."}},{"id":"exp-02-seg-3","startSeconds":135,"endSeconds":215,"text":{"en":"[Stage 3: Glowing splint oxygen test] Touching a glowing splint to the foam causes it to relight into flame, proving the gas is O₂. Scientific context: When iodide ions (I⁻) are added, they provide an alternative two-step pathway via hypoiodite (IO⁻) with a much lower activation energy: Step 1: H₂O₂ + I⁻ → H₂O + IO⁻; Step 2: H₂O₂ + IO⁻ → H₂O + O₂ (g) + I⁻. Notice that I⁻ is regenerated in Step 2, acting as a true catalyst while releasing ~196 kJ of heat per 2 moles of H₂O₂.","ky":"[3-баскыч: Кычкылтекти чырпык менен текшерүү] Чок болуп турган чырпыкты көбүккө тийгизгенде ал кайра жанат — бул O₂ газынын далили. Илимий түшүндүрмө: Иодид иондору (I⁻) кошулганда реакция эки баскычтуу жеңил жол менен жүрөт: 1) H₂O₂ + I⁻ → H₂O + IO⁻; 2) H₂O₂ + IO⁻ → H₂O + O₂↑ + I⁻. Натыйжада I⁻ кайра калыбына келет, ал эми бөлүнүп чыккан кычкылтек самынды көбүртөт.","ru":"[Этап 3: Проверка кислорода тлеющей лучинкой] Тлеющая лучинка ярко вспыхивает в пене, доказывая, что пузырьки заполнены чистым O₂. Научное объяснение: Иодид-ионы (I⁻) открывают двухстадийный путь через гипоиодит-ион (IO⁻) с низкой энергией активации: 1) H₂O₂ + I⁻ → H₂O + IO⁻; 2) H₂O₂ + IO⁻ → H₂O + O₂↑ + I⁻. Катализатор I⁻ регенерируется, а бурно выделяющийся кислород вспенивает мыльный раствор с выделением тепла."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('electrolysis-of-water-hoffman','{"id":"exp-03","slug":"electrolysis-of-water-hoffman","topicId":"electrochemistry","durationSeconds":300,"safetyLevel":"student_lab","featured":true,"youtubeVideo":"https://www.youtube.com/watch?v=HQ9Fhd7P_HA","chemicalEquation":"2H₂O (l) —[DC current, Na₂SO₄]→ 2H₂ (g, cathode) + O₂ (g, anode)","illustration":"electrolysis-tubes","title":{"en":"Electrolysis of Water","ky":"Суунун электролизи","ru":"Электролиз воды"},"shortDescription":{"en":"Split liquid water with direct current and verify visually why twice as much hydrogen collects at the cathode as oxygen at the anode.","ky":"Туруктуу ток аркылуу сууну ажыратып, катоддо эмне үчүн кычкылтекке караганда эки эсе көп суутек чогуларын далилдеңиз.","ru":"Разложите воду постоянным током и убедитесь, почему на катоде собирается ровно вдвое больше водорода, чем кислорода на аноде."},"objectives":{"en":["Connect the 2:1 volume ratio of H₂ to O₂ gas directly to the formula of water (H₂O) and Avogadro''s law.","Explain why an inert electrolyte (such as Na₂SO₄) is added to pure distilled water.","Identify cathode reduction and anode oxidation half-reactions."],"ky":["H₂ менен O₂ газдарынын 2:1 көлөмдүк катышын суунун формуласы (H₂O) менен байланыштыруу.","Таза сууга эмне үчүн электролит (Na₂SO₄) кошуларын түшүндүрүү.","Катоддогу калыбына келүү жана аноддогу кычкылдануу процесстерин айырмалоо."],"ru":["Связать соотношение объёмов H₂ и O₂ (2:1) с формулой воды H₂O и законом Авогадро.","Объяснить, зачем к дистиллированной воде добавляют фоновый электролит (Na₂SO₄).","Записать полуреакции восстановления на катоде и окисления на аноде."]},"materials":{"en":["Hoffman voltameter or beaker with 2 inverted graduated tubes","Inert platinum or stainless-steel electrodes","DC power supply (9–12 V)","Distilled water + 0.1 M sodium sulfate (Na₂SO₄)","Bromothymol blue indicator (optional)","Matches & wooden splints"],"ky":["Гофман аппараты же 2 пробиркалуу идиш","Инерттүү электроддор","Туруктуу ток булагы (9–12 В)","Дистилденген суу + натрий сульфаты (Na₂SO₄)","Бромтимол көк индикатору","Ширенке жана чырпыктар"],"ru":["Аппарат Гофмана или стакан с 2 градуированными пробирками","Инертные электроды","Источник постоянного тока (9–12 В)","Дистиллированная вода + сульфат натрия Na₂SO₄ (0,1 М)","Индикатор бромтимоловый синий","Лучинки и спички"]},"safetyNotes":{"en":["Use only low-voltage DC power (9–12 V) and disconnect power before adjusting electrodes.","Do not use table salt (NaCl) as the electrolyte in an open room, as chloride ions oxidize at the anode to produce toxic chlorine gas (Cl₂)."],"ky":["Төмөн чыңалуудагы туруктуу токту (9–12 В) гана колдонуңуз.","Аш тузун (NaCl) колдонбоңуз, анткени аноддо уулуу хлор газы (Cl₂) бөлүнүп чыгышы мүмкүн."],"ru":["Используйте только низковольтный источник постоянного тока (9–12 В).","Не используйте поваренную соль (NaCl) вместо Na₂SO₄, так как на аноде будет выделяться токсичный хлор (Cl₂)."]},"scientificExplanation":{"en":["Pure water has an extremely low concentration of ions ([H⁺] = [OH⁻] = 10⁻⁷ M), making it a poor conductor. Dissolving sodium sulfate (Na₂SO₄) supplies mobile Na⁺ and SO₄²⁻ ions that carry charge without being discharged themselves.","At the negative cathode, water molecules gain electrons (reduction): 4H₂O + 4e⁻ → 2H₂ (g) + 4OH⁻. At the positive anode, water molecules lose electrons (oxidation): 2H₂O → O₂ (g) + 4H⁺ + 4e⁻. Passing 4 moles of electrons produces 2 moles of H₂ and 1 mole of O₂."],"ky":["Таза сууда иондор өтө аз болгондуктан токту начар өткөрөт. Натрий сульфатын (Na₂SO₄) кошуу эритменин электр өткөрүмдүүлүгүн жогорулатат.","Терс катоддо суутек бөлүнүп чыгат: 4H₂O + 4e⁻ → 2H₂↑ + 4OH⁻. Оң аноддо кычкылтек бөлүнүп чыгат: 2H₂O → O₂↑ + 4H⁺ + 4e⁻. Ар бир 4 электрон өткөндө 2 моль H₂ жана 1 моль O₂ пайда болот."],"ru":["Чистая вода почти не проводит ток ([H⁺] = 10⁻⁷ М). Добавление сульфата натрия (Na₂SO₄) обеспечивает ионную проводимость, при этом ионы Na⁺ и SO₄²⁻ не разряжаются на электродах.","На катоде (−) идёт восстановление: 4H₂O + 4e⁻ → 2H₂↑ + 4OH⁻. На аноде (+) идёт окисление: 2H₂O → O₂↑ + 4H⁺ + 4e⁻. Суммарно на каждые 4 моль электронов выделяется 2 моль H₂ и 1 моль O₂."]},"steps":[{"timeSeconds":20,"title":{"en":"Fill graduated tubes with electrolyte","ky":"Пробиркаларды электролит менен толтуруу","ru":"Заполнение трубок электролитом"},"detail":{"en":"Invert both liquid-filled tubes over the electrodes with zero trapped air bubbles.","ky":"Эки пробирканы тең аба көбүкчөлөрүн калтырбай электролит менен толтуруп электроддорго орнотобуз.","ru":"Заполняем обе градуированные трубки раствором Na₂SO₄ без пузырьков воздуха."}},{"timeSeconds":90,"title":{"en":"Apply DC voltage & observe 2:1 gas collection","ky":"Ток берип, 2:1 катышын байкоо","ru":"Подача тока и наблюдение соотношения 2:1"},"detail":{"en":"Fine bubbles stream from both electrodes; the cathode tube fills with gas twice as fast as the anode tube.","ky":"Катоддогу пробиркада анодго караганда газ эки эсе бат топтолот.","ru":"Пузырьки газа поднимаются с обоих электродов; объём газа над катодом ровно вдвое превышает объём над анодом."}},{"timeSeconds":210,"title":{"en":"Pop test & glowing splint verification","ky":"Газдарды текшерүү","ru":"Идентификация H₂ и O₂"},"detail":{"en":"Cathode gas gives a ''pop'' with a flame (H₂); anode gas relights a glowing splint (O₂).","ky":"Катоддогу газ жалында «пылк» этип күйөт (H₂), аноддогу газ чокту жандырат (O₂).","ru":"Газ с катода сгорает с хлопком (H₂), а газ с анода воспламеняет тлеющую лучинку (O₂)."}}],"quiz":[{"id":"q1","prompt":{"en":"If 18 mL of oxygen gas (O₂) collects above the anode during water electrolysis, what volume of hydrogen gas (H₂) should collect above the cathode at the same temperature and pressure?","ky":"Эгерде суунун электролизинде аноддо 18 мл кычкылтек (O₂) чогулса, ошол эле шартта катоддо канча көлөмдөгү суутек (H₂) чогулат?","ru":"Если над анодом при электролизе воды собралось 18 мл кислорода (O₂), какой объём водорода (H₂) соберётся над катодом при тех же условиях?"},"conceptTag":"electrochemistry","options":[{"id":"a","text":{"en":"9 mL","ky":"9 мл","ru":"9 мл"}},{"id":"b","text":{"en":"36 mL","ky":"36 мл","ru":"36 мл"}},{"id":"c","text":{"en":"18 mL","ky":"18 мл","ru":"18 мл"}}]}],"transcriptSegments":[{"id":"exp-03-seg-1","startSeconds":0,"endSeconds":90,"text":{"en":"[Stage 1: Fill graduated tubes with electrolyte] Invert both liquid-filled tubes over the electrodes with zero trapped air bubbles. Scientific context: Pure water has an extremely low concentration of ions ([H⁺] = [OH⁻] = 10⁻⁷ M), making it a poor conductor. Dissolving sodium sulfate (Na₂SO₄) supplies mobile Na⁺ and SO₄²⁻ ions that carry charge without being discharged themselves.","ky":"[1-баскыч: Пробиркаларды электролит менен толтуруу] Эки пробирканы тең аба көбүкчөлөрүн калтырбай электролит менен толтуруп электроддорго орнотобуз. Илимий түшүндүрмө: Таза сууда иондор өтө аз болгондуктан токту начар өткөрөт. Натрий сульфатын (Na₂SO₄) кошуу эритменин электр өткөрүмдүүлүгүн жогорулатат.","ru":"[Этап 1: Заполнение трубок электролитом] Заполняем обе градуированные трубки раствором Na₂SO₄ без пузырьков воздуха. Научное объяснение: Чистая вода почти не проводит ток ([H⁺] = 10⁻⁷ М). Добавление сульфата натрия (Na₂SO₄) обеспечивает ионную проводимость, при этом ионы Na⁺ и SO₄²⁻ не разряжаются на электродах."}},{"id":"exp-03-seg-2","startSeconds":90,"endSeconds":210,"text":{"en":"[Stage 2: Apply DC voltage & observe 2:1 gas collection] Fine bubbles stream from both electrodes; the cathode tube fills with gas twice as fast as the anode tube. Scientific context: At the negative cathode, water molecules gain electrons (reduction): 4H₂O + 4e⁻ → 2H₂ (g) + 4OH⁻. At the positive anode, water molecules lose electrons (oxidation): 2H₂O → O₂ (g) + 4H⁺ + 4e⁻. Passing 4 moles of electrons produces 2 moles of H₂ and 1 mole of O₂.","ky":"[2-баскыч: Ток берип, 2:1 катышын байкоо] Катоддогу пробиркада анодго караганда газ эки эсе бат топтолот. Илимий түшүндүрмө: Терс катоддо суутек бөлүнүп чыгат: 4H₂O + 4e⁻ → 2H₂↑ + 4OH⁻. Оң аноддо кычкылтек бөлүнүп чыгат: 2H₂O → O₂↑ + 4H⁺ + 4e⁻. Ар бир 4 электрон өткөндө 2 моль H₂ жана 1 моль O₂ пайда болот.","ru":"[Этап 2: Подача тока и наблюдение соотношения 2:1] Пузырьки газа поднимаются с обоих электродов; объём газа над катодом ровно вдвое превышает объём над анодом. Научное объяснение: На катоде (−) идёт восстановление: 4H₂O + 4e⁻ → 2H₂↑ + 4OH⁻. На аноде (+) идёт окисление: 2H₂O → O₂↑ + 4H⁺ + 4e⁻. Суммарно на каждые 4 моль электронов выделяется 2 моль H₂ и 1 моль O₂."}},{"id":"exp-03-seg-3","startSeconds":210,"endSeconds":300,"text":{"en":"[Stage 3: Pop test & glowing splint verification] Cathode gas gives a ''pop'' with a flame (H₂); anode gas relights a glowing splint (O₂). Scientific context: At the negative cathode, water molecules gain electrons (reduction): 4H₂O + 4e⁻ → 2H₂ (g) + 4OH⁻. At the positive anode, water molecules lose electrons (oxidation): 2H₂O → O₂ (g) + 4H⁺ + 4e⁻. Passing 4 moles of electrons produces 2 moles of H₂ and 1 mole of O₂.","ky":"[3-баскыч: Газдарды текшерүү] Катоддогу газ жалында «пылк» этип күйөт (H₂), аноддогу газ чокту жандырат (O₂). Илимий түшүндүрмө: Терс катоддо суутек бөлүнүп чыгат: 4H₂O + 4e⁻ → 2H₂↑ + 4OH⁻. Оң аноддо кычкылтек бөлүнүп чыгат: 2H₂O → O₂↑ + 4H⁺ + 4e⁻. Ар бир 4 электрон өткөндө 2 моль H₂ жана 1 моль O₂ пайда болот.","ru":"[Этап 3: Идентификация H₂ и O₂] Газ с катода сгорает с хлопком (H₂), а газ с анода воспламеняет тлеющую лучинку (O₂). Научное объяснение: На катоде (−) идёт восстановление: 4H₂O + 4e⁻ → 2H₂↑ + 4OH⁻. На аноде (+) идёт окисление: 2H₂O → O₂↑ + 4H⁺ + 4e⁻. Суммарно на каждые 4 моль электронов выделяется 2 моль H₂ и 1 моль O₂."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('iron-nail-copper-sulfate-displacement','{"id":"exp-04","slug":"iron-nail-copper-sulfate-displacement","topicId":"metals","durationSeconds":200,"safetyLevel":"student_lab","featured":true,"youtubeVideo":"https://www.youtube.com/watch?v=T4pSuflO9fk","chemicalEquation":"Fe (s) + CuSO₄ (aq, blue) → FeSO₄ (aq, pale green) + Cu (s, salmon-red)","illustration":"copper-displacement","title":{"en":"Iron Nail in Copper Sulfate","ky":"Темир мык жана жез сульфаты","ru":"Железный гвоздь в сульфате меди"},"shortDescription":{"en":"Observe metallic copper plate onto a steel nail while the bright blue Cu²⁺ solution fades to pale green Fe²⁺.","ky":"Темир мыктын бетине кызыл жез чөгүп, көк Cu²⁺ эритмеси ачык жашыл Fe²⁺ өңүнө өтүшүн байкаңыз.","ru":"Наблюдайте осаждение красной меди на поверхности железного гвоздя и переход голубой окраски Cu²⁺ в бледно-зелёную Fe²⁺."},"objectives":{"en":["Use the metal reactivity series to predict why iron displaces copper from CuSO₄(aq).","Connect the color shift of the liquid (blue → pale green) to the replacement of Cu²⁺(aq) by Fe²⁺(aq)."],"ky":["Металлдардын активдүүлүк катары боюнча темир жезди эмне үчүн сүрүп чыгарарын түшүндүрүү.","Эритменин көктөн ачык жашылга өтүшүн Cu²⁺ иондорунун Fe²⁺ иондору менен алмашуусу аркылуу далилдөө."],"ru":["Объяснить вытеснение меди железом с помощью ряда активности металлов.","Связать изменение цвета раствора (голубой → бледно-зелёный) с переходом ионов Cu²⁺ в Fe²⁺."]},"materials":{"en":["Clean iron nails (sanded with emery paper)","0.5 M Copper(II) sulfate (CuSO₄) solution","2 test tubes (1 control, 1 reaction)","Forceps & filter paper","Safety goggles"],"ky":["Тазаланган темир мыктар","0.5 М Жез(II) сульфатынын (CuSO₄) эритмеси","2 пробирка (салыштыруу үчүн)","Пинцет жана чыпка кагазы","Коргоочу көз айнек"],"ru":["Очищенные железные гвозди","0,5 М раствор сульфата меди(II) CuSO₄","2 пробирки (контрольная и рабочая)","Пинцет и фильтровальная бумага","Защитные очки"]},"safetyNotes":{"en":["Copper(II) sulfate solution is harmful if swallowed and irritating to eyes; wash hands after the lab.","Do not pour heavy-metal copper solutions down the sink; collect in the labeled waste bottle."],"ky":["Жез(II) сульфаты көзгө жана териге зыяндуу; тажрыйбадан кийин колду самындап жууңуз.","Жез эритмелерин раковинага төкпөстөн, атайын калдык идишке чогултуңуз."],"ru":["Раствор сульфата меди(II) токсичен при проглатывании и раздражает глаза; мойте руки после работы.","Сливайте отработанные растворы солей меди в специальную ёмкость для отходов."]},"scientificExplanation":{"en":["Iron lies above copper in the electrochemical reactivity series (E°(Fe²⁺/Fe) = −0.44 V vs. E°(Cu²⁺/Cu) = +0.34 V). Iron atoms on the nail surface transfer two valence electrons directly to hydrated Cu²⁺ ions: Fe(s) + Cu²⁺(aq) → Fe²⁺(aq) + Cu(s).","Neutral copper atoms deposit as a reddish-brown coating on the nail, while Fe²⁺ ions enter solution, gradually shifting the color from sky blue to pale green."],"ky":["Металлдардын активдүүлүк катарында темир жезден сол жакта жайгашкан. Темир атомдору эки электронун Cu²⁺ иондоруна берет: Fe(к) + Cu²⁺(эр) → Fe²⁺(эр) + Cu(к).","Натыйжада мыктын бетине кызгылт жез капталып, эритме Fe²⁺ иондорунун эсебинен ачык жашыл түскө өтөт."],"ru":["Железо стоит левее меди в электрохимическом ряду напряжений металлов (E°(Fe²⁺/Fe) = −0,44 В против E°(Cu²⁺/Cu) = +0,34 В). Атомы железа отдают по два электрона ионам меди: Fe(тв) + Cu²⁺(р-р) → Fe²⁺(р-р) + Cu(тв).","Восстановленная медь оседает рыхлым розово-красным слоем на гвозде, а накопление ионов Fe²⁺ меняет окраску раствора с голубой на бледно-зелёную."]},"steps":[{"timeSeconds":15,"title":{"en":"Polish the iron nail","ky":"Темир мыкты тазалоо","ru":"Зачистка железного гвоздя"},"detail":{"en":"Remove any surface oxide layer with sandpaper so bare iron metal contacts the solution.","ky":"Мыктын бетиндеги датты кум кагаз менен тазалайбыз.","ru":"Удаляем оксидную плёнку наждачной бумагой для чистого контакта металла с раствором."}},{"timeSeconds":60,"title":{"en":"Immerse in CuSO₄ & compare with control","ky":"CuSO₄ эритмесине салуу","ru":"Погружение в раствор CuSO₄"},"detail":{"en":"Within 30 seconds a copper layer forms on the submerged nail; keep a second tube of CuSO₄ beside it to compare color.","ky":"30 секунданын ичинде мыктын бети жез менен капталат; өңдү контролдук пробирка менен салыштырабыз.","ru":"Уже через 30 секунд гвоздь покрывается красным налётом меди; сравниваем цвет раствора с контрольной пробиркой."}}],"quiz":[{"id":"q1","prompt":{"en":"What would you observe if a strip of copper metal (Cu) were placed into a solution of iron(II) sulfate (FeSO₄)?","ky":"Эгерде жез пластинкасын (Cu) темир(II) сульфатынын (FeSO₄) эритмесине салсак эмне байкалат?","ru":"Что произойдёт, если опустить медную пластинку (Cu) в раствор сульфата железа(II) FeSO₄?"},"conceptTag":"metals","options":[{"id":"a","text":{"en":"No reaction occurs because copper is less reactive than iron and cannot reduce Fe²⁺ ions.","ky":"Реакция жүрбөйт, анткени жез темирге караганда пассивдүү жана Fe²⁺ иондорун сүрүп чыгара албайт.","ru":"Реакция не пойдёт, так как медь менее активна, чем железо, и не может восстановить ионы Fe²⁺."}},{"id":"b","text":{"en":"Grey iron metal immediately plates onto the copper strip.","ky":"Жез пластинканын бетине дароо боз темир чөгөт.","ru":"На медной пластинке сразу выделится слой серого железа."}}]}],"transcriptSegments":[{"id":"exp-04-seg-1","startSeconds":0,"endSeconds":60,"text":{"en":"[Stage 1: Polish the iron nail] Remove any surface oxide layer with sandpaper so bare iron metal contacts the solution. Scientific context: Iron lies above copper in the electrochemical reactivity series (E°(Fe²⁺/Fe) = −0.44 V vs. E°(Cu²⁺/Cu) = +0.34 V). Iron atoms on the nail surface transfer two valence electrons directly to hydrated Cu²⁺ ions: Fe(s) + Cu²⁺(aq) → Fe²⁺(aq) + Cu(s).","ky":"[1-баскыч: Темир мыкты тазалоо] Мыктын бетиндеги датты кум кагаз менен тазалайбыз. Илимий түшүндүрмө: Металлдардын активдүүлүк катарында темир жезден сол жакта жайгашкан. Темир атомдору эки электронун Cu²⁺ иондоруна берет: Fe(к) + Cu²⁺(эр) → Fe²⁺(эр) + Cu(к).","ru":"[Этап 1: Зачистка железного гвоздя] Удаляем оксидную плёнку наждачной бумагой для чистого контакта металла с раствором. Научное объяснение: Железо стоит левее меди в электрохимическом ряду напряжений металлов (E°(Fe²⁺/Fe) = −0,44 В против E°(Cu²⁺/Cu) = +0,34 В). Атомы железа отдают по два электрона ионам меди: Fe(тв) + Cu²⁺(р-р) → Fe²⁺(р-р) + Cu(тв)."}},{"id":"exp-04-seg-2","startSeconds":60,"endSeconds":200,"text":{"en":"[Stage 2: Immerse in CuSO₄ & compare with control] Within 30 seconds a copper layer forms on the submerged nail; keep a second tube of CuSO₄ beside it to compare color. Scientific context: Neutral copper atoms deposit as a reddish-brown coating on the nail, while Fe²⁺ ions enter solution, gradually shifting the color from sky blue to pale green.","ky":"[2-баскыч: CuSO₄ эритмесине салуу] 30 секунданын ичинде мыктын бети жез менен капталат; өңдү контролдук пробирка менен салыштырабыз. Илимий түшүндүрмө: Натыйжада мыктын бетине кызгылт жез капталып, эритме Fe²⁺ иондорунун эсебинен ачык жашыл түскө өтөт.","ru":"[Этап 2: Погружение в раствор CuSO₄] Уже через 30 секунд гвоздь покрывается красным налётом меди; сравниваем цвет раствора с контрольной пробиркой. Научное объяснение: Восстановленная медь оседает рыхлым розово-красным слоем на гвозде, а накопление ионов Fe²⁺ меняет окраску раствора с голубой на бледно-зелёную."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('flame-tests-metal-cations','{"id":"exp-05","slug":"flame-tests-metal-cations","topicId":"energy","durationSeconds":245,"safetyLevel":"teacher_demo","featured":true,"youtubeVideo":"https://www.youtube.com/watch?v=1EXr_L7Ojqg","chemicalEquation":"M⁺ (ground state) + thermal energy → M⁺* (excited) → M⁺ + hν (characteristic photon)","illustration":"flame-spectrum","title":{"en":"Flame Colors of Metals","ky":"Металлдардын жалынынын өңү","ru":"Окрашивание пламени металлами"},"shortDescription":{"en":"Identify metal cations by the characteristic wavelengths of light emitted when thermally excited electrons return to lower energy levels.","ky":"Козголгон электрондор төмөнкү деңгээлге кайтканда чыккан жалындын өңү аркылуу металл иондорун тааныңыз.","ru":"Распознавайте катионы металлов по характерному цвету пламени, возникающему при переходе электронов на нижние энергетические уровни."},"objectives":{"en":["Match Li⁺ (crimson), Na⁺ (intense yellow), K⁺ (lilac), Sr²⁺ (scarlet), and Cu²⁺ (blue-green) to their flame colors.","Explain how quantized electron energy jumps produce specific photon wavelengths (ΔE = hc/λ)."],"ky":["Li⁺ (кочкул кызыл), Na⁺ (сары), K⁺ (кызгылт-көк), Cu²⁺ (жашыл-көк) иондорун жалындын өңү боюнча айырмалоо.","Электрондордун энергетикалык секириктери эмне үчүн белгилүү бир өңдөгү жарыкты чыгарарын түшүндүрүү (ΔE = hc/λ)."],"ru":["Сопоставить катионы Li⁺ (карминово-красный), Na⁺ (жёлтый), K⁺ (фиолетовый), Cu²⁺ (зелёный) с цветом пламени.","Объяснить связь между квантованными переходами электронов и длиной волны излучения (ΔE = hc/λ)."]},"materials":{"en":["Nichrome or platinum wire loop","Bunsen burner (non-luminous blue flame)","Chloride salts: LiCl, NaCl, KCl, SrCl₂, BaCl₂, CuCl₂","Dilute HCl for cleaning wire","Cobalt blue glass (for viewing K⁺)"],"ky":["Нихром же платина зымы","Бунзен күйгүзгүчү (көк жалын)","Хлорид туздары: LiCl, NaCl, KCl, SrCl₂, CuCl₂","Зымды тазалоо үчүн суюлтулган HCl","Кобальт айнеги (K⁺ көрүү үчүн)"],"ru":["Нихромовая или платиновая петля","Горелка Бунзена (несветящееся синее пламя)","Хлориды LiCl, NaCl, KCl, SrCl₂, CuCl₂","Разбавленная HCl для очистки петли","Кобальтовое стекло (для наблюдения K⁺)"]},"safetyNotes":{"en":["Tie back long hair and wear safety goggles when operating an open Bunsen burner flame.","Barium and copper salts are toxic — avoid inhaling salt aerosols and perform in a well-ventilated lab."],"ky":["Ачык жалын менен иштегенде чачты жыйнап, коргоочу көз айнек тагыныңыз.","Жез жана барий туздары уулуу — бөлмөнү жакшы желдетиңиз."],"ru":["Соблюдайте правила работы с открытым пламенем горелки и используйте защитные очки.","Соли бария и меди токсичны — проводите опыт в хорошо проветриваемом помещении."]},"scientificExplanation":{"en":["Thermal energy from the burner flame vaporizes the metal chloride and promotes outer-shell electrons to higher, unstable orbitals. When those electrons relax back to lower orbitals, each transition releases a photon with energy ΔE = hc/λ.","Because every element has a unique spacing of atomic orbitals, each metal emits a signature line spectrum — such as sodium''s intense 589 nm yellow doublet or copper''s green-blue emission."],"ky":["Жалындын жылуулук энергиясы металл атомдорунун сырткы электрондорун жогорку энергетикалык деңгээлге чыгарат. Электрондор кайра өз ордуна кайтканда ΔE = hc/λ энергиялуу фотон бөлүнүп чыгат.","Ар бир элементтин энергетикалык деңгээлдеринин айырмасы уникалдуу болгондуктан, ар бир металл өзүнө гана мүнөздүү өң менен күйөт (мисалы, натрий 589 нм сары жарык чыгарат)."],"ru":["Тепловая энергия пламени переводит валентные электроны атомов и ионов металлов на более высокие энергетические уровни. Возвращаясь в основное состояние, электроны испускают фотоны с энергией ΔE = hc/λ.","Поскольку набор энергетических уровней каждого элемента уникален, каждый металл даёт характерный спектр излучения (например, жёлтый дублет натрия 589 нм)."]},"steps":[{"timeSeconds":20,"title":{"en":"Clean wire loop in HCl & blue flame","ky":"Зымды HCl жана жалында тазалоо","ru":"Очистка петли в HCl и пламени"},"detail":{"en":"Dip the nichrome loop in dilute HCl and heat until no residual color appears in the blue burner cone.","ky":"Нихром зымын HCl эритмесине малып, жалындын өңү өзгөрбөй калганга чейин ысытабыз.","ru":"Прокаливаем петлю после смачивания в HCl до исчезновения посторонней окраски пламени."}},{"timeSeconds":85,"title":{"en":"Test Li⁺, Na⁺, K⁺, Sr²⁺, and Cu²⁺","ky":"Катиондорду жалынга кармоо","ru":"Внесение солей Li⁺, Na⁺, K⁺, Sr²⁺ и Cu²⁺"},"detail":{"en":"Observe crimson (Li⁺), bright gold-yellow (Na⁺), lilac through cobalt glass (K⁺), and emerald blue-green (Cu²⁺).","ky":"Кочкул кызыл (Li⁺), ачык сары (Na⁺), кызгылт-көк (K⁺) жана көгүш-жашыл (Cu²⁺) жалынды байкайбыз.","ru":"Наблюдаем карминово-красное (Li⁺), ярко-жёлтое (Na⁺), фиолетовое (K⁺) и изумрудно-зелёное (Cu²⁺) пламя."}}],"quiz":[{"id":"q1","prompt":{"en":"An unknown white chloride salt produces a vivid emerald blue-green flame in a Bunsen burner. Which metal cation is present?","ky":"Белгисиз ак туз Бунзен жалынында ачык көгүш-жашыл өң менен күйөт. Анын курамында кайсы металлдын катиону бар?","ru":"Неизвестная соль окрашивает пламя горелки в яркий изумрудно-зелёный цвет. Какой катион металла присутствует в пробе?"},"conceptTag":"energy","options":[{"id":"a","text":{"en":"Sodium (Na⁺)","ky":"Натрий (Na⁺)","ru":"Натрий (Na⁺)"}},{"id":"b","text":{"en":"Copper (Cu²⁺)","ky":"Жез (Cu²⁺)","ru":"Медь (Cu²⁺)"}}]}],"transcriptSegments":[{"id":"exp-05-seg-1","startSeconds":0,"endSeconds":85,"text":{"en":"[Stage 1: Clean wire loop in HCl & blue flame] Dip the nichrome loop in dilute HCl and heat until no residual color appears in the blue burner cone. Scientific context: Thermal energy from the burner flame vaporizes the metal chloride and promotes outer-shell electrons to higher, unstable orbitals. When those electrons relax back to lower orbitals, each transition releases a photon with energy ΔE = hc/λ.","ky":"[1-баскыч: Зымды HCl жана жалында тазалоо] Нихром зымын HCl эритмесине малып, жалындын өңү өзгөрбөй калганга чейин ысытабыз. Илимий түшүндүрмө: Жалындын жылуулук энергиясы металл атомдорунун сырткы электрондорун жогорку энергетикалык деңгээлге чыгарат. Электрондор кайра өз ордуна кайтканда ΔE = hc/λ энергиялуу фотон бөлүнүп чыгат.","ru":"[Этап 1: Очистка петли в HCl и пламени] Прокаливаем петлю после смачивания в HCl до исчезновения посторонней окраски пламени. Научное объяснение: Тепловая энергия пламени переводит валентные электроны атомов и ионов металлов на более высокие энергетические уровни. Возвращаясь в основное состояние, электроны испускают фотоны с энергией ΔE = hc/λ."}},{"id":"exp-05-seg-2","startSeconds":85,"endSeconds":245,"text":{"en":"[Stage 2: Test Li⁺, Na⁺, K⁺, Sr²⁺, and Cu²⁺] Observe crimson (Li⁺), bright gold-yellow (Na⁺), lilac through cobalt glass (K⁺), and emerald blue-green (Cu²⁺). Scientific context: Because every element has a unique spacing of atomic orbitals, each metal emits a signature line spectrum — such as sodium''s intense 589 nm yellow doublet or copper''s green-blue emission.","ky":"[2-баскыч: Катиондорду жалынга кармоо] Кочкул кызыл (Li⁺), ачык сары (Na⁺), кызгылт-көк (K⁺) жана көгүш-жашыл (Cu²⁺) жалынды байкайбыз. Илимий түшүндүрмө: Ар бир элементтин энергетикалык деңгээлдеринин айырмасы уникалдуу болгондуктан, ар бир металл өзүнө гана мүнөздүү өң менен күйөт (мисалы, натрий 589 нм сары жарык чыгарат).","ru":"[Этап 2: Внесение солей Li⁺, Na⁺, K⁺, Sr²⁺ и Cu²⁺] Наблюдаем карминово-красное (Li⁺), ярко-жёлтое (Na⁺), фиолетовое (K⁺) и изумрудно-зелёное (Cu²⁺) пламя. Научное объяснение: Поскольку набор энергетических уровней каждого элемента уникален, каждый металл даёт характерный спектр излучения (например, жёлтый дублет натрия 589 нм)."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('paper-chromatography-plant-ink-pigments','{"id":"exp-06","slug":"paper-chromatography-plant-ink-pigments","topicId":"separation","durationSeconds":230,"safetyLevel":"student_lab","featured":true,"youtubeVideo":"https://www.youtube.com/watch?v=ZCzgQXGz9Tg","chemicalEquation":"Rf = (distance traveled by pigment) / (distance traveled by solvent front)","illustration":"chromatography-strip","title":{"en":"Paper Chromatography","ky":"Кагаз хроматографиясы","ru":"Бумажная хроматография"},"shortDescription":{"en":"Separate a single black ink spot into distinct dye bands and calculate retention factors (Rf) based on polarity.","ky":"Кара сыянын чекитин түстүү боёкторго ажыратып, Rf кармалуу коэффициентин эсептеңиз.","ru":"Разделите каплю чёрных чернил на отдельные красители и рассчитайте коэффициент удерживания Rf."},"objectives":{"en":["Explain separation in chromatography as a competition between the stationary phase (cellulose + water) and mobile phase.","Calculate the retention factor Rf = d(solute) / d(solvent) and understand why Rf is always ≤ 1.0."],"ky":["Кыймылсыз фаза (целлюлоза) менен кыймылдуу фазанын (эриткич) ортосундагы бөлүнүү принцибин түшүндүрүү.","Rf = d(зат) / d(эриткич) формуласы боюнча кармалуу коэффициентин эсептөө."],"ru":["Объяснить принцип распределения вещества между неподвижной (целлюлоза) и подвижной фазами.","Рассчитать фактор удерживания Rf = d(вещества) / d(растворителя)."]},"materials":{"en":["Chromatography or filter paper strips","Water-soluble black, green, and purple markers","Pencil (for baseline!)","Beaker with shallow water/ethanol eluent","Ruler & wooden splint clip"],"ky":["Хроматографиялык же чыпка кагазы","Сууда эрүүчү фломастерлер","Карандаш (старт сызыгы үчүн!)","Суу же спирт куюлган стакан","Сызгыч"],"ru":["Полоски хроматографической или фильтровальной бумаги","Водорастворимые фломастеры","Простой карандаш (для линии старта!)","Стакан с элюентом (вода / этанол)","Линейка"]},"safetyNotes":{"en":["If using ethanol or isopropyl alcohol as the mobile phase, keep away from flames and cover the beaker with a watch glass."],"ky":["Эгерде эриткич катары этил спирти колдонулса, ачык оттон алыс кармаңыз."],"ru":["При использовании этанола или изопропанола в качестве элюента работайте вдали от открытого огня."]},"scientificExplanation":{"en":["Capillary action draws the liquid solvent (mobile phase) upward through the cellulose fibers of the paper (stationary phase). Dye molecules that form stronger hydrogen bonds with the stationary phase move slowly (low Rf), whereas dyes that are more soluble in the mobile phase travel near the solvent front (high Rf).","The baseline must always be drawn in graphite pencil rather than pen ink, because graphite is insoluble and will not elute with the solvent."],"ky":["Капиллярдык кубулуштун эсебинен эриткич кагаз өйдө көтөрүлөт. Эриткичте жакшы эриген пигменттер тез көтөрүлөт (жогорку Rf), ал эми кагазга күчтүүрөөк тартылган заттар жай жылат (төмөнкү Rf).","Старт сызыгы сөзсүз жөнөкөй карандаш менен чийилет, анткени графит эриткичте эрибейт."],"ru":["Под действием капиллярных сил растворитель (подвижная фаза) поднимается по волокнам целлюлозы (неподвижная фаза). Красители, лучше растворимые в подвижной фазе, движутся быстрее (высокий Rf), а сильнее адсорбирующиеся на бумаге — медленнее (низкий Rf).","Линию старта всегда проводят простым карандашом, так как графит не растворяется в элюенте."]},"steps":[{"timeSeconds":20,"title":{"en":"Draw pencil baseline & spot sample","ky":"Карандаш менен сызык чийип, чекит коюу","ru":"Нанесение линии старта карандашом и пробы"},"detail":{"en":"Draw a pencil line 2 cm from the bottom edge, apply a concentrated ink dot, and let it dry.","ky":"Кагаздын түбүнөн 2 см жогору карандаш менен сызып, сыя чекитин тамызабыз.","ru":"На высоте 2 см от края проводим линию карандашом и наносим маленькую точку чернил."}},{"timeSeconds":95,"title":{"en":"Develop chromatogram above solvent level","ky":"Хроматограмманы өстүрүү","ru":"Развитие хроматограммы"},"detail":{"en":"Suspend the strip so only the tip touches the liquid — keep the ink spot above the water level!","ky":"Кагаздын учу гана сууга тийгидей кылып асып коёбуз — сыя чекити суунун деңгээлинен жогору турушу шарт!","ru":"Погружаем только нижний край бумаги — точка старта должна оставаться выше уровня жидкости!"}}],"quiz":[{"id":"q1","prompt":{"en":"Why must the starting line on a chromatography strip be drawn with a graphite pencil instead of a ballpoint pen?","ky":"Эмне үчүн хроматография кагазындагы баштапкы сызыкты ручка менен эмес, жөнөкөй карандаш менен чийүү керек?","ru":"Почему стартовую линию на хроматографической бумаге проводят графитовым карандашом, а не ручкой?"},"conceptTag":"separation","options":[{"id":"a","text":{"en":"Graphite is insoluble in the mobile phase, whereas pen ink would dissolve and travel up the paper, contaminating the sample bands.","ky":"Графит эриткичте эрибейт, ал эми ручканын сыясы эрип кетип, тажрыйбанын жыйынтыгын бузат.","ru":"Графит нерастворим в элюенте, тогда как чернила ручки растворятся и смешаются с исследуемыми пигментами."}},{"id":"b","text":{"en":"Graphite acts as a catalyst that speeds up capillary action.","ky":"Графит капиллярдык кыймылды тездетүүчү катализатор болуп саналат.","ru":"Графит служит катализатором, ускоряющим подъём воды."}}]}],"transcriptSegments":[{"id":"exp-06-seg-1","startSeconds":0,"endSeconds":95,"text":{"en":"[Stage 1: Draw pencil baseline & spot sample] Draw a pencil line 2 cm from the bottom edge, apply a concentrated ink dot, and let it dry. Scientific context: Capillary action draws the liquid solvent (mobile phase) upward through the cellulose fibers of the paper (stationary phase). Dye molecules that form stronger hydrogen bonds with the stationary phase move slowly (low Rf), whereas dyes that are more soluble in the mobile phase travel near the solvent front (high Rf).","ky":"[1-баскыч: Карандаш менен сызык чийип, чекит коюу] Кагаздын түбүнөн 2 см жогору карандаш менен сызып, сыя чекитин тамызабыз. Илимий түшүндүрмө: Капиллярдык кубулуштун эсебинен эриткич кагаз өйдө көтөрүлөт. Эриткичте жакшы эриген пигменттер тез көтөрүлөт (жогорку Rf), ал эми кагазга күчтүүрөөк тартылган заттар жай жылат (төмөнкү Rf).","ru":"[Этап 1: Нанесение линии старта карандашом и пробы] На высоте 2 см от края проводим линию карандашом и наносим маленькую точку чернил. Научное объяснение: Под действием капиллярных сил растворитель (подвижная фаза) поднимается по волокнам целлюлозы (неподвижная фаза). Красители, лучше растворимые в подвижной фазе, движутся быстрее (высокий Rf), а сильнее адсорбирующиеся на бумаге — медленнее (низкий Rf)."}},{"id":"exp-06-seg-2","startSeconds":95,"endSeconds":230,"text":{"en":"[Stage 2: Develop chromatogram above solvent level] Suspend the strip so only the tip touches the liquid — keep the ink spot above the water level! Scientific context: The baseline must always be drawn in graphite pencil rather than pen ink, because graphite is insoluble and will not elute with the solvent.","ky":"[2-баскыч: Хроматограмманы өстүрүү] Кагаздын учу гана сууга тийгидей кылып асып коёбуз — сыя чекити суунун деңгээлинен жогору турушу шарт! Илимий түшүндүрмө: Старт сызыгы сөзсүз жөнөкөй карандаш менен чийилет, анткени графит эриткичте эрибейт.","ru":"[Этап 2: Развитие хроматограммы] Погружаем только нижний край бумаги — точка старта должна оставаться выше уровня жидкости! Научное объяснение: Линию старта всегда проводят простым карандашом, так как графит не растворяется в элюенте."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('acid-base-titration-phenolphthalein','{"id":"exp-07","slug":"acid-base-titration-phenolphthalein","topicId":"acids-bases","durationSeconds":275,"safetyLevel":"student_lab","youtubeVideo":"https://www.youtube.com/watch?v=sFpFCPTDv2w","chemicalEquation":"HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l)","illustration":"indicator-flask","title":{"en":"Acid–Base Titration","ky":"Кислота-негиздик титрлөө","ru":"Кислотно-основное титрование"},"shortDescription":{"en":"Deliver NaOH drop-by-drop from a burette to catch the exact equivalence point where colorless solution turns faint pink.","ky":"Бюреткадан NaOH тамчылатып кошуп, түссүз эритме мала кызыл өңгө өткөн эквиваленттик чекитти табыңыз.","ru":"Добавляйте NaOH по каплям из бюретки до появления устойчивой бледно-малиновой окраски фенолфталеина."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Acid–Base Neutralization & Phenolphthalein Endpoint and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Acids & Bases.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["«Кислота менен негиздин нейтралдашуусу (фенолфталеин менен титрлөө)» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Кислоталар жана негиздер» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте «Реакция нейтрализации и титрование с фенолфталеином» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Кислоты и основания».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Deliver NaOH drop-by-drop from a burette to catch the exact equivalence point where colorless solution turns faint pink.","Reaction summary: HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Бюреткадан NaOH тамчылатып кошуп, түссүз эритме мала кызыл өңгө өткөн эквиваленттик чекитти табыңыз.","Процесстин негизги теңдемеси: HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Добавляйте NaOH по каплям из бюретки до появления устойчивой бледно-малиновой окраски фенолфталеина.","Схема процесса: HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Deliver NaOH drop-by-drop from a burette to catch the exact equivalence point where colorless solution turns faint pink.","ky":"Бюреткадан NaOH тамчылатып кошуп, түссүз эритме мала кызыл өңгө өткөн эквиваленттик чекитти табыңыз.","ru":"Добавляйте NaOH по каплям из бюретки до появления устойчивой бледно-малиновой окраски фенолфталеина."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l).","ky":"HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l) теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l)."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Acid–Base Neutralization & Phenolphthalein Endpoint\"?","ky":"«Кислота менен негиздин нейтралдашуусу (фенолфталеин менен титрлөө)» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Реакция нейтрализации и титрование с фенолфталеином»?"},"conceptTag":"acids-bases","options":[{"id":"a","text":{"en":"HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l)","ky":"HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l)","ru":"HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l)"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"Acid–Base Neutralization & Phenolphthalein Endpoint\"?","ky":"«Кислота менен негиздин нейтралдашуусу (фенолфталеин менен титрлөө)» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Реакция нейтрализации и титрование с фенолфталеином»?"},"conceptTag":"acids-bases","options":[{"id":"a","text":{"en":"Deliver NaOH drop-by-drop from a burette to catch the exact equivalence point where colorless solution turns faint pink.","ky":"Бюреткадан NaOH тамчылатып кошуп, түссүз эритме мала кызыл өңгө өткөн эквиваленттик чекитти табыңыз.","ru":"Добавляйте NaOH по каплям из бюретки до появления устойчивой бледно-малиновой окраски фенолфталеина."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-07-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Deliver NaOH drop-by-drop from a burette to catch the exact equivalence point where colorless solution turns faint pink.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Бюреткадан NaOH тамчылатып кошуп, түссүз эритме мала кызыл өңгө өткөн эквиваленттик чекитти табыңыз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Добавляйте NaOH по каплям из бюретки до появления устойчивой бледно-малиновой окраски фенолфталеина."}},{"id":"exp-07-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Deliver NaOH drop-by-drop from a burette to catch the exact equivalence point where colorless solution turns faint pink. Scientific context: Reaction summary: HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Бюреткадан NaOH тамчылатып кошуп, түссүз эритме мала кызыл өңгө өткөн эквиваленттик чекитти табыңыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Добавляйте NaOH по каплям из бюретки до появления устойчивой бледно-малиновой окраски фенолфталеина. Научное объяснение: Схема процесса: HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-07-seg-3","startSeconds":145,"endSeconds":275,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). Scientific context: Reaction summary: HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l) теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). Научное объяснение: Схема процесса: HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('universal-indicator-ph-column','{"id":"exp-08","slug":"universal-indicator-ph-column","topicId":"acids-bases","durationSeconds":195,"safetyLevel":"teacher_demo","youtubeVideo":"https://www.youtube.com/watch?v=I18K2upEHLc","chemicalEquation":"CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12)","illustration":"indicator-flask","title":{"en":"pH Rainbow Column","ky":"Цилиндрдеги pH спектри","ru":"Радужная колонка pH"},"shortDescription":{"en":"Create a vertical density gradient from dense sodium carbonate at the bottom to dilute acid at the top, displaying the full pH spectrum.","ky":"Түбүндө тыгыз сода эритмеси, үстүндө кислота жайгашкан вертикалдуу спектр түзүңүз.","ru":"Создайте градиент плотности и pH в высоком цилиндре от красного наверху до фиолетового внизу."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Density & pH Rainbow Column in a Graduated Cylinder and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Acids & Bases.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["«Цилиндрдеги тыгыздык жана универсалдуу индикатордун pH-санжырасы» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Кислоталар жана негиздер» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте «Радужная колонка pH с универсальным индикатором» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Кислоты и основания».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Create a vertical density gradient from dense sodium carbonate at the bottom to dilute acid at the top, displaying the full pH spectrum.","Reaction summary: CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Түбүндө тыгыз сода эритмеси, үстүндө кислота жайгашкан вертикалдуу спектр түзүңүз.","Процесстин негизги теңдемеси: CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Создайте градиент плотности и pH в высоком цилиндре от красного наверху до фиолетового внизу.","Схема процесса: CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Create a vertical density gradient from dense sodium carbonate at the bottom to dilute acid at the top, displaying the full pH spectrum.","ky":"Түбүндө тыгыз сода эритмеси, үстүндө кислота жайгашкан вертикалдуу спектр түзүңүз.","ru":"Создайте градиент плотности и pH в высоком цилиндре от красного наверху до фиолетового внизу."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12).","ky":"CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12) теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12)."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Density & pH Rainbow Column in a Graduated Cylinder\"?","ky":"«Цилиндрдеги тыгыздык жана универсалдуу индикатордун pH-санжырасы» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Радужная колонка pH с универсальным индикатором»?"},"conceptTag":"acids-bases","options":[{"id":"a","text":{"en":"CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12)","ky":"CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12)","ru":"CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12)"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"Density & pH Rainbow Column in a Graduated Cylinder\"?","ky":"«Цилиндрдеги тыгыздык жана универсалдуу индикатордун pH-санжырасы» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Радужная колонка pH с универсальным индикатором»?"},"conceptTag":"acids-bases","options":[{"id":"a","text":{"en":"Create a vertical density gradient from dense sodium carbonate at the bottom to dilute acid at the top, displaying the full pH spectrum.","ky":"Түбүндө тыгыз сода эритмеси, үстүндө кислота жайгашкан вертикалдуу спектр түзүңүз.","ru":"Создайте градиент плотности и pH в высоком цилиндре от красного наверху до фиолетового внизу."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-08-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Create a vertical density gradient from dense sodium carbonate at the bottom to dilute acid at the top, displaying the full pH spectrum.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Түбүндө тыгыз сода эритмеси, үстүндө кислота жайгашкан вертикалдуу спектр түзүңүз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Создайте градиент плотности и pH в высоком цилиндре от красного наверху до фиолетового внизу."}},{"id":"exp-08-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Create a vertical density gradient from dense sodium carbonate at the bottom to dilute acid at the top, displaying the full pH spectrum. Scientific context: Reaction summary: CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Түбүндө тыгыз сода эритмеси, үстүндө кислота жайгашкан вертикалдуу спектр түзүңүз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Создайте градиент плотности и pH в высоком цилиндре от красного наверху до фиолетового внизу. Научное объяснение: Схема процесса: CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-08-seg-3","startSeconds":145,"endSeconds":195,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). Scientific context: Reaction summary: CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12) теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). Научное объяснение: Схема процесса: CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('iodine-clock-reaction-kinetics','{"id":"exp-09","slug":"iodine-clock-reaction-kinetics","topicId":"reactions","durationSeconds":250,"safetyLevel":"teacher_demo","youtubeVideo":"https://www.youtube.com/watch?v=NTFBXJ3Zd_4","chemicalEquation":"IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue)","illustration":"peroxide-foam","title":{"en":"The Iodine Clock Reaction","ky":"Йод сааты реакциясы","ru":"Реакция «Йодные часы»"},"shortDescription":{"en":"Mix two colorless liquids and time how concentration and temperature control the sudden flash to deep blue-black starch-iodine complex.","ky":"Эки түссүз эритмени кошуп, концентрация менен температура кочкул көк өңдүн пайда болуу убактысына кантип таасир этерин ченеңиз.","ru":"Измерьте время до внезапного посинения раствора при разных концентрациях реагентов и температурах."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in The Iodine Clock Reaction: Visualizing Reaction Rates and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Chemical Reactions.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["«Йод сааты реакциясы: Химиялык ылдамдыкты визуалдык байкоо» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Химиялык реакциялар» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте «Йодные часы: наглядная кинетика химических реакций» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Химические реакции».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Mix two colorless liquids and time how concentration and temperature control the sudden flash to deep blue-black starch-iodine complex.","Reaction summary: IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Эки түссүз эритмени кошуп, концентрация менен температура кочкул көк өңдүн пайда болуу убактысына кантип таасир этерин ченеңиз.","Процесстин негизги теңдемеси: IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Измерьте время до внезапного посинения раствора при разных концентрациях реагентов и температурах.","Схема процесса: IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Mix two colorless liquids and time how concentration and temperature control the sudden flash to deep blue-black starch-iodine complex.","ky":"Эки түссүз эритмени кошуп, концентрация менен температура кочкул көк өңдүн пайда болуу убактысына кантип таасир этерин ченеңиз.","ru":"Измерьте время до внезапного посинения раствора при разных концентрациях реагентов и температурах."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue).","ky":"IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue) теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue)."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"The Iodine Clock Reaction: Visualizing Reaction Rates\"?","ky":"«Йод сааты реакциясы: Химиялык ылдамдыкты визуалдык байкоо» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Йодные часы: наглядная кинетика химических реакций»?"},"conceptTag":"reactions","options":[{"id":"a","text":{"en":"IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue)","ky":"IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue)","ru":"IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue)"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"The Iodine Clock Reaction: Visualizing Reaction Rates\"?","ky":"«Йод сааты реакциясы: Химиялык ылдамдыкты визуалдык байкоо» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Йодные часы: наглядная кинетика химических реакций»?"},"conceptTag":"reactions","options":[{"id":"a","text":{"en":"Mix two colorless liquids and time how concentration and temperature control the sudden flash to deep blue-black starch-iodine complex.","ky":"Эки түссүз эритмени кошуп, концентрация менен температура кочкул көк өңдүн пайда болуу убактысына кантип таасир этерин ченеңиз.","ru":"Измерьте время до внезапного посинения раствора при разных концентрациях реагентов и температурах."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-09-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Mix two colorless liquids and time how concentration and temperature control the sudden flash to deep blue-black starch-iodine complex.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Эки түссүз эритмени кошуп, концентрация менен температура кочкул көк өңдүн пайда болуу убактысына кантип таасир этерин ченеңиз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Измерьте время до внезапного посинения раствора при разных концентрациях реагентов и температурах."}},{"id":"exp-09-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Mix two colorless liquids and time how concentration and temperature control the sudden flash to deep blue-black starch-iodine complex. Scientific context: Reaction summary: IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Эки түссүз эритмени кошуп, концентрация менен температура кочкул көк өңдүн пайда болуу убактысына кантип таасир этерин ченеңиз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Измерьте время до внезапного посинения раствора при разных концентрациях реагентов и температурах. Научное объяснение: Схема процесса: IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-09-seg-3","startSeconds":145,"endSeconds":250,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). Scientific context: Reaction summary: IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue) теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). Научное объяснение: Схема процесса: IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('golden-rain-lead-iodide-precipitation','{"id":"exp-10","slug":"golden-rain-lead-iodide-precipitation","topicId":"reactions","durationSeconds":220,"safetyLevel":"teacher_demo","youtubeVideo":"https://www.youtube.com/watch?v=TRkL2_bde9I","chemicalEquation":"Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq)","illustration":"crystal-lattice","title":{"en":"Golden Rain Crystals","ky":"«Алтын жамгыр» кристаллдары","ru":"Кристаллы «Золотой дождь»"},"shortDescription":{"en":"Dissolve yellow PbI₂ precipitate in hot water and watch hexagonal golden crystal platelets snow down as the solution cools.","ky":"Сары PbI₂ чөкмөсүн ысык сууда эритип, муздаганда алтын сымал жалтырак кристаллдардын кантип түшөрүн көрүңүз.","ru":"Наблюдайте выпадение сверкающих золотистых шестиугольных кристаллов PbI₂ при охлаждении горячего раствора."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Golden Rain: Recrystallization of Lead(II) Iodide and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Chemical Reactions.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["««Алтын жамгыр»: Коргошун(II) иодидинин чөгүшү жана кристаллдашуусу» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Химиялык реакциялар» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте ««Золотой дождь»: осаждение и перекристаллизация иодида свинца(II)» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Химические реакции».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Dissolve yellow PbI₂ precipitate in hot water and watch hexagonal golden crystal platelets snow down as the solution cools.","Reaction summary: Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Сары PbI₂ чөкмөсүн ысык сууда эритип, муздаганда алтын сымал жалтырак кристаллдардын кантип түшөрүн көрүңүз.","Процесстин негизги теңдемеси: Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Наблюдайте выпадение сверкающих золотистых шестиугольных кристаллов PbI₂ при охлаждении горячего раствора.","Схема процесса: Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Dissolve yellow PbI₂ precipitate in hot water and watch hexagonal golden crystal platelets snow down as the solution cools.","ky":"Сары PbI₂ чөкмөсүн ысык сууда эритип, муздаганда алтын сымал жалтырак кристаллдардын кантип түшөрүн көрүңүз.","ru":"Наблюдайте выпадение сверкающих золотистых шестиугольных кристаллов PbI₂ при охлаждении горячего раствора."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq).","ky":"Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq) теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq)."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Golden Rain: Recrystallization of Lead(II) Iodide\"?","ky":"««Алтын жамгыр»: Коргошун(II) иодидинин чөгүшү жана кристаллдашуусу» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте ««Золотой дождь»: осаждение и перекристаллизация иодида свинца(II)»?"},"conceptTag":"reactions","options":[{"id":"a","text":{"en":"Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq)","ky":"Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq)","ru":"Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq)"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"Golden Rain: Recrystallization of Lead(II) Iodide\"?","ky":"««Алтын жамгыр»: Коргошун(II) иодидинин чөгүшү жана кристаллдашуусу» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте ««Золотой дождь»: осаждение и перекристаллизация иодида свинца(II)»?"},"conceptTag":"reactions","options":[{"id":"a","text":{"en":"Dissolve yellow PbI₂ precipitate in hot water and watch hexagonal golden crystal platelets snow down as the solution cools.","ky":"Сары PbI₂ чөкмөсүн ысык сууда эритип, муздаганда алтын сымал жалтырак кристаллдардын кантип түшөрүн көрүңүз.","ru":"Наблюдайте выпадение сверкающих золотистых шестиугольных кристаллов PbI₂ при охлаждении горячего раствора."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-10-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Dissolve yellow PbI₂ precipitate in hot water and watch hexagonal golden crystal platelets snow down as the solution cools.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Сары PbI₂ чөкмөсүн ысык сууда эритип, муздаганда алтын сымал жалтырак кристаллдардын кантип түшөрүн көрүңүз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Наблюдайте выпадение сверкающих золотистых шестиугольных кристаллов PbI₂ при охлаждении горячего раствора."}},{"id":"exp-10-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Dissolve yellow PbI₂ precipitate in hot water and watch hexagonal golden crystal platelets snow down as the solution cools. Scientific context: Reaction summary: Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Сары PbI₂ чөкмөсүн ысык сууда эритип, муздаганда алтын сымал жалтырак кристаллдардын кантип түшөрүн көрүңүз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Наблюдайте выпадение сверкающих золотистых шестиугольных кристаллов PbI₂ при охлаждении горячего раствора. Научное объяснение: Схема процесса: Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-10-seg-3","startSeconds":145,"endSeconds":220,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). Scientific context: Reaction summary: Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq) теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). Научное объяснение: Схема процесса: Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('burning-magnesium-ribbon-in-air','{"id":"exp-11","slug":"burning-magnesium-ribbon-in-air","topicId":"reactions","durationSeconds":165,"safetyLevel":"teacher_demo","youtubeVideo":"https://www.youtube.com/watch?v=m2i9jLPX7_E","chemicalEquation":"2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder)","illustration":"flame-spectrum","title":{"en":"Burning Magnesium Ribbon","ky":"Магний тасмасынын күйүшү","ru":"Горение магниевой ленты"},"shortDescription":{"en":"Observe the brilliant white oxidation of magnesium metal and test the resulting MgO ash in water with an indicator.","ky":"Магнийдин көздү уялткан ак жалын менен күйүшүн жана пайда болгон MgO күлүнүн суудагы щелочтук чөйрөсүн текшериңиз.","ru":"Яркое окисление магния на воздухе и проверка щелочной реакции образующегося оксида MgO."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Combustion of Magnesium Ribbon & Basic Oxide Test and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Chemical Reactions.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["«Магний тасмасынын күйүшү жана негиздик оксидди текшерүү» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Химиялык реакциялар» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте «Горение магниевой ленты и свойства оксида магния» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Химические реакции».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Observe the brilliant white oxidation of magnesium metal and test the resulting MgO ash in water with an indicator.","Reaction summary: 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Магнийдин көздү уялткан ак жалын менен күйүшүн жана пайда болгон MgO күлүнүн суудагы щелочтук чөйрөсүн текшериңиз.","Процесстин негизги теңдемеси: 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Яркое окисление магния на воздухе и проверка щелочной реакции образующегося оксида MgO.","Схема процесса: 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Observe the brilliant white oxidation of magnesium metal and test the resulting MgO ash in water with an indicator.","ky":"Магнийдин көздү уялткан ак жалын менен күйүшүн жана пайда болгон MgO күлүнүн суудагы щелочтук чөйрөсүн текшериңиз.","ru":"Яркое окисление магния на воздухе и проверка щелочной реакции образующегося оксида MgO."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder).","ky":"2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder) теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder)."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Combustion of Magnesium Ribbon & Basic Oxide Test\"?","ky":"«Магний тасмасынын күйүшү жана негиздик оксидди текшерүү» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Горение магниевой ленты и свойства оксида магния»?"},"conceptTag":"reactions","options":[{"id":"a","text":{"en":"2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder)","ky":"2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder)","ru":"2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder)"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"Combustion of Magnesium Ribbon & Basic Oxide Test\"?","ky":"«Магний тасмасынын күйүшү жана негиздик оксидди текшерүү» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Горение магниевой ленты и свойства оксида магния»?"},"conceptTag":"reactions","options":[{"id":"a","text":{"en":"Observe the brilliant white oxidation of magnesium metal and test the resulting MgO ash in water with an indicator.","ky":"Магнийдин көздү уялткан ак жалын менен күйүшүн жана пайда болгон MgO күлүнүн суудагы щелочтук чөйрөсүн текшериңиз.","ru":"Яркое окисление магния на воздухе и проверка щелочной реакции образующегося оксида MgO."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-11-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Observe the brilliant white oxidation of magnesium metal and test the resulting MgO ash in water with an indicator.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Магнийдин көздү уялткан ак жалын менен күйүшүн жана пайда болгон MgO күлүнүн суудагы щелочтук чөйрөсүн текшериңиз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Яркое окисление магния на воздухе и проверка щелочной реакции образующегося оксида MgO."}},{"id":"exp-11-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Observe the brilliant white oxidation of magnesium metal and test the resulting MgO ash in water with an indicator. Scientific context: Reaction summary: 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Магнийдин көздү уялткан ак жалын менен күйүшүн жана пайда болгон MgO күлүнүн суудагы щелочтук чөйрөсүн текшериңиз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Яркое окисление магния на воздухе и проверка щелочной реакции образующегося оксида MgO. Научное объяснение: Схема процесса: 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-11-seg-3","startSeconds":145,"endSeconds":165,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). Scientific context: Reaction summary: 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder) теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). Научное объяснение: Схема процесса: 2Mg (s) + O₂ (g) → 2MgO (s, white basic oxide powder). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('hydrogen-gas-generation-pop-test','{"id":"exp-12","slug":"hydrogen-gas-generation-pop-test","topicId":"gases","durationSeconds":210,"safetyLevel":"student_lab","youtubeVideo":"https://www.youtube.com/watch?v=4F72V61114I","chemicalEquation":"Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑","illustration":"gas-splint","title":{"en":"Hydrogen Gas Pop Test","ky":"Суутек газын алуу жана текшерүү","ru":"Получение и проверка водорода"},"shortDescription":{"en":"React zinc granules with dilute hydrochloric acid, collect H₂ by upward delivery, and verify with the characteristic squeaky pop.","ky":"Цинк гранулаларын туз кислотасы менен реакцияга киргизип, жеңил суутек газын чогултуп текшериңиз.","ru":"Взаимодействие гранул цинка с соляной кислотой, сбор лёгкого газа H₂ и характерный хлопок при поджигании."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Generating Hydrogen Gas (Zn + HCl) & the ''Pop'' Test and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Gas Tests.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["«Суутек газын алуу (Zn + HCl) жана «пылк» эткен үн менен текшерүү» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Газдарды аныктоо» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте «Получение водорода (Zn + HCl) и проверка на чистоту» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Опыты с газами».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["React zinc granules with dilute hydrochloric acid, collect H₂ by upward delivery, and verify with the characteristic squeaky pop.","Reaction summary: Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Цинк гранулаларын туз кислотасы менен реакцияга киргизип, жеңил суутек газын чогултуп текшериңиз.","Процесстин негизги теңдемеси: Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Взаимодействие гранул цинка с соляной кислотой, сбор лёгкого газа H₂ и характерный хлопок при поджигании.","Схема процесса: Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"React zinc granules with dilute hydrochloric acid, collect H₂ by upward delivery, and verify with the characteristic squeaky pop.","ky":"Цинк гранулаларын туз кислотасы менен реакцияга киргизип, жеңил суутек газын чогултуп текшериңиз.","ru":"Взаимодействие гранул цинка с соляной кислотой, сбор лёгкого газа H₂ и характерный хлопок при поджигании."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑.","ky":"Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑ теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Generating Hydrogen Gas (Zn + HCl) & the ''Pop'' Test\"?","ky":"«Суутек газын алуу (Zn + HCl) жана «пылк» эткен үн менен текшерүү» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Получение водорода (Zn + HCl) и проверка на чистоту»?"},"conceptTag":"gases","options":[{"id":"a","text":{"en":"Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑","ky":"Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑","ru":"Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"Generating Hydrogen Gas (Zn + HCl) & the ''Pop'' Test\"?","ky":"«Суутек газын алуу (Zn + HCl) жана «пылк» эткен үн менен текшерүү» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Получение водорода (Zn + HCl) и проверка на чистоту»?"},"conceptTag":"gases","options":[{"id":"a","text":{"en":"React zinc granules with dilute hydrochloric acid, collect H₂ by upward delivery, and verify with the characteristic squeaky pop.","ky":"Цинк гранулаларын туз кислотасы менен реакцияга киргизип, жеңил суутек газын чогултуп текшериңиз.","ru":"Взаимодействие гранул цинка с соляной кислотой, сбор лёгкого газа H₂ и характерный хлопок при поджигании."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-12-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: React zinc granules with dilute hydrochloric acid, collect H₂ by upward delivery, and verify with the characteristic squeaky pop.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Цинк гранулаларын туз кислотасы менен реакцияга киргизип, жеңил суутек газын чогултуп текшериңиз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Взаимодействие гранул цинка с соляной кислотой, сбор лёгкого газа H₂ и характерный хлопок при поджигании."}},{"id":"exp-12-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] React zinc granules with dilute hydrochloric acid, collect H₂ by upward delivery, and verify with the characteristic squeaky pop. Scientific context: Reaction summary: Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Цинк гранулаларын туз кислотасы менен реакцияга киргизип, жеңил суутек газын чогултуп текшериңиз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Взаимодействие гранул цинка с соляной кислотой, сбор лёгкого газа H₂ и характерный хлопок при поджигании. Научное объяснение: Схема процесса: Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-12-seg-3","startSeconds":145,"endSeconds":210,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. Scientific context: Reaction summary: Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑ теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. Научное объяснение: Схема процесса: Zn (s) + 2HCl (aq) → ZnCl₂ (aq) + H₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('carbon-dioxide-limewater-candle-test','{"id":"exp-13","slug":"carbon-dioxide-limewater-candle-test","topicId":"gases","durationSeconds":205,"safetyLevel":"student_lab","youtubeVideo":"https://www.youtube.com/watch?v=b7d4b3G9jB0","chemicalEquation":"CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑","illustration":"gas-splint","title":{"en":"Carbon Dioxide Tests","ky":"Көмүр кычкыл газын таануу","ru":"Опыты с углекислым газом"},"shortDescription":{"en":"Generate CO₂ from marble chips, bubble it through Ca(OH)₂ to form milky CaCO₃, and pour the dense gas to extinguish stepped candles.","ky":"Мрамор кесимдеринен CO₂ алып, акиташ суусун ылайлатып жана абадан оор газды куюп шамды өчүрүңүз.","ru":"Получение CO₂ из мрамора, помутнение известковой воды и «переливание» тяжёлого газа на горящие свечи."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Carbon Dioxide (CO₂): Limewater Test & Pouring a Heavy Gas and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Gas Tests.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["«Көмүр кычкыл газы (CO₂): Акиташ суусун ылайлатуу жана шамды өчүрүү» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Газдарды аныктоо» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте «Углекислый газ (CO₂): реакция с известковой водой и тушение свечи» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Опыты с газами».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Generate CO₂ from marble chips, bubble it through Ca(OH)₂ to form milky CaCO₃, and pour the dense gas to extinguish stepped candles.","Reaction summary: CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Мрамор кесимдеринен CO₂ алып, акиташ суусун ылайлатып жана абадан оор газды куюп шамды өчүрүңүз.","Процесстин негизги теңдемеси: CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Получение CO₂ из мрамора, помутнение известковой воды и «переливание» тяжёлого газа на горящие свечи.","Схема процесса: CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Generate CO₂ from marble chips, bubble it through Ca(OH)₂ to form milky CaCO₃, and pour the dense gas to extinguish stepped candles.","ky":"Мрамор кесимдеринен CO₂ алып, акиташ суусун ылайлатып жана абадан оор газды куюп шамды өчүрүңүз.","ru":"Получение CO₂ из мрамора, помутнение известковой воды и «переливание» тяжёлого газа на горящие свечи."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑.","ky":"CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑ теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Carbon Dioxide (CO₂): Limewater Test & Pouring a Heavy Gas\"?","ky":"«Көмүр кычкыл газы (CO₂): Акиташ суусун ылайлатуу жана шамды өчүрүү» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Углекислый газ (CO₂): реакция с известковой водой и тушение свечи»?"},"conceptTag":"gases","options":[{"id":"a","text":{"en":"CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑","ky":"CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑","ru":"CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"Carbon Dioxide (CO₂): Limewater Test & Pouring a Heavy Gas\"?","ky":"«Көмүр кычкыл газы (CO₂): Акиташ суусун ылайлатуу жана шамды өчүрүү» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Углекислый газ (CO₂): реакция с известковой водой и тушение свечи»?"},"conceptTag":"gases","options":[{"id":"a","text":{"en":"Generate CO₂ from marble chips, bubble it through Ca(OH)₂ to form milky CaCO₃, and pour the dense gas to extinguish stepped candles.","ky":"Мрамор кесимдеринен CO₂ алып, акиташ суусун ылайлатып жана абадан оор газды куюп шамды өчүрүңүз.","ru":"Получение CO₂ из мрамора, помутнение известковой воды и «переливание» тяжёлого газа на горящие свечи."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-13-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Generate CO₂ from marble chips, bubble it through Ca(OH)₂ to form milky CaCO₃, and pour the dense gas to extinguish stepped candles.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Мрамор кесимдеринен CO₂ алып, акиташ суусун ылайлатып жана абадан оор газды куюп шамды өчүрүңүз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Получение CO₂ из мрамора, помутнение известковой воды и «переливание» тяжёлого газа на горящие свечи."}},{"id":"exp-13-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Generate CO₂ from marble chips, bubble it through Ca(OH)₂ to form milky CaCO₃, and pour the dense gas to extinguish stepped candles. Scientific context: Reaction summary: CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Мрамор кесимдеринен CO₂ алып, акиташ суусун ылайлатып жана абадан оор газды куюп шамды өчүрүңүз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Получение CO₂ из мрамора, помутнение известковой воды и «переливание» тяжёлого газа на горящие свечи. Научное объяснение: Схема процесса: CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-13-seg-3","startSeconds":145,"endSeconds":205,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. Scientific context: Reaction summary: CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑ теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. Научное объяснение: Схема процесса: CaCO₃ (s) + 2HCl (aq) → CaCl₂ (aq) + H₂O (l) + CO₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('oxygen-generation-glowing-splint','{"id":"exp-14","slug":"oxygen-generation-glowing-splint","topicId":"gases","durationSeconds":190,"safetyLevel":"student_lab","youtubeVideo":"https://www.youtube.com/watch?v=p1eG2y2mn54","chemicalEquation":"2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑","illustration":"gas-splint","title":{"en":"Generating Oxygen Gas","ky":"Кычкылтек алуу жана текшерүү","ru":"Получение кислорода"},"shortDescription":{"en":"Collect pure oxygen over water using manganese(IV) oxide catalyst and watch a glowing wooden splint burst back into bright flame.","ky":"Марганец(IV) оксидинин жардамы менен суу астында кычкылтек чогултуп, чок болуп турган чырпыкты жандырыңыз.","ru":"Сбор кислорода методом вытеснения воды и яркое воспламенение тлеющей лучинки."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Laboratory Preparation of Oxygen & Glowing Splint Test and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Gas Tests.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["«Лабораторияда кычкылтек алуу (MnO₂ менен) жана чокту жандыруу» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Газдарды аныктоо» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте «Лабораторное получение кислорода (с MnO₂) и опыт с тлеющей лучинкой» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Опыты с газами».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Collect pure oxygen over water using manganese(IV) oxide catalyst and watch a glowing wooden splint burst back into bright flame.","Reaction summary: 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Марганец(IV) оксидинин жардамы менен суу астында кычкылтек чогултуп, чок болуп турган чырпыкты жандырыңыз.","Процесстин негизги теңдемеси: 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Сбор кислорода методом вытеснения воды и яркое воспламенение тлеющей лучинки.","Схема процесса: 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Collect pure oxygen over water using manganese(IV) oxide catalyst and watch a glowing wooden splint burst back into bright flame.","ky":"Марганец(IV) оксидинин жардамы менен суу астында кычкылтек чогултуп, чок болуп турган чырпыкты жандырыңыз.","ru":"Сбор кислорода методом вытеснения воды и яркое воспламенение тлеющей лучинки."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑.","ky":"2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑ теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Laboratory Preparation of Oxygen & Glowing Splint Test\"?","ky":"«Лабораторияда кычкылтек алуу (MnO₂ менен) жана чокту жандыруу» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Лабораторное получение кислорода (с MnO₂) и опыт с тлеющей лучинкой»?"},"conceptTag":"gases","options":[{"id":"a","text":{"en":"2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑","ky":"2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑","ru":"2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"Laboratory Preparation of Oxygen & Glowing Splint Test\"?","ky":"«Лабораторияда кычкылтек алуу (MnO₂ менен) жана чокту жандыруу» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Лабораторное получение кислорода (с MnO₂) и опыт с тлеющей лучинкой»?"},"conceptTag":"gases","options":[{"id":"a","text":{"en":"Collect pure oxygen over water using manganese(IV) oxide catalyst and watch a glowing wooden splint burst back into bright flame.","ky":"Марганец(IV) оксидинин жардамы менен суу астында кычкылтек чогултуп, чок болуп турган чырпыкты жандырыңыз.","ru":"Сбор кислорода методом вытеснения воды и яркое воспламенение тлеющей лучинки."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-14-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Collect pure oxygen over water using manganese(IV) oxide catalyst and watch a glowing wooden splint burst back into bright flame.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Марганец(IV) оксидинин жардамы менен суу астында кычкылтек чогултуп, чок болуп турган чырпыкты жандырыңыз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Сбор кислорода методом вытеснения воды и яркое воспламенение тлеющей лучинки."}},{"id":"exp-14-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Collect pure oxygen over water using manganese(IV) oxide catalyst and watch a glowing wooden splint burst back into bright flame. Scientific context: Reaction summary: 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Марганец(IV) оксидинин жардамы менен суу астында кычкылтек чогултуп, чок болуп турган чырпыкты жандырыңыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Сбор кислорода методом вытеснения воды и яркое воспламенение тлеющей лучинки. Научное объяснение: Схема процесса: 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-14-seg-3","startSeconds":145,"endSeconds":190,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. Scientific context: Reaction summary: 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑ теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. Научное объяснение: Схема процесса: 2H₂O₂ (aq) —[MnO₂]→ 2H₂O (l) + O₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('silver-tree-copper-silver-nitrate','{"id":"exp-15","slug":"silver-tree-copper-silver-nitrate","topicId":"metals","durationSeconds":240,"safetyLevel":"teacher_demo","youtubeVideo":"https://www.youtube.com/watch?v=p8qD42jC6nE","chemicalEquation":"Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓","illustration":"copper-displacement","title":{"en":"Silver Crystal Tree","ky":"«Күмүш дарагын» өстүрүү","ru":"Выращивание «Серебряного дерева»"},"shortDescription":{"en":"Suspend a coiled copper wire in colorless silver nitrate solution and watch delicate metallic silver dendrites branch out while the liquid turns blue.","ky":"Түссүз күмүш нитратына салынган жез зымда жалтырак күмүш ийнечелери өсүп, эритме көк өңгө өтүшүн көрүңүз.","ru":"Рост сверкающих дендритов металлического серебра на медной спирали и посинение раствора за счёт ионов Cu²⁺."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Growing a Silver Crystal Tree on Copper Wire and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Metals & Reactivity.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["««Күмүш дарагы»: Жез зымда күмүш кристаллдарынын өсүшү» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Металлдар» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте ««Серебряное дерево»: вытеснение серебра медью из раствора AgNO₃» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Металлы и активность».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Suspend a coiled copper wire in colorless silver nitrate solution and watch delicate metallic silver dendrites branch out while the liquid turns blue.","Reaction summary: Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Түссүз күмүш нитратына салынган жез зымда жалтырак күмүш ийнечелери өсүп, эритме көк өңгө өтүшүн көрүңүз.","Процесстин негизги теңдемеси: Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Рост сверкающих дендритов металлического серебра на медной спирали и посинение раствора за счёт ионов Cu²⁺.","Схема процесса: Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Suspend a coiled copper wire in colorless silver nitrate solution and watch delicate metallic silver dendrites branch out while the liquid turns blue.","ky":"Түссүз күмүш нитратына салынган жез зымда жалтырак күмүш ийнечелери өсүп, эритме көк өңгө өтүшүн көрүңүз.","ru":"Рост сверкающих дендритов металлического серебра на медной спирали и посинение раствора за счёт ионов Cu²⁺."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓.","ky":"Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓ теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Growing a Silver Crystal Tree on Copper Wire\"?","ky":"««Күмүш дарагы»: Жез зымда күмүш кристаллдарынын өсүшү» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте ««Серебряное дерево»: вытеснение серебра медью из раствора AgNO₃»?"},"conceptTag":"metals","options":[{"id":"a","text":{"en":"Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓","ky":"Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓","ru":"Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"Growing a Silver Crystal Tree on Copper Wire\"?","ky":"««Күмүш дарагы»: Жез зымда күмүш кристаллдарынын өсүшү» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте ««Серебряное дерево»: вытеснение серебра медью из раствора AgNO₃»?"},"conceptTag":"metals","options":[{"id":"a","text":{"en":"Suspend a coiled copper wire in colorless silver nitrate solution and watch delicate metallic silver dendrites branch out while the liquid turns blue.","ky":"Түссүз күмүш нитратына салынган жез зымда жалтырак күмүш ийнечелери өсүп, эритме көк өңгө өтүшүн көрүңүз.","ru":"Рост сверкающих дендритов металлического серебра на медной спирали и посинение раствора за счёт ионов Cu²⁺."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-15-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Suspend a coiled copper wire in colorless silver nitrate solution and watch delicate metallic silver dendrites branch out while the liquid turns blue.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Түссүз күмүш нитратына салынган жез зымда жалтырак күмүш ийнечелери өсүп, эритме көк өңгө өтүшүн көрүңүз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Рост сверкающих дендритов металлического серебра на медной спирали и посинение раствора за счёт ионов Cu²⁺."}},{"id":"exp-15-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Suspend a coiled copper wire in colorless silver nitrate solution and watch delicate metallic silver dendrites branch out while the liquid turns blue. Scientific context: Reaction summary: Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Түссүз күмүш нитратына салынган жез зымда жалтырак күмүш ийнечелери өсүп, эритме көк өңгө өтүшүн көрүңүз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Рост сверкающих дендритов металлического серебра на медной спирали и посинение раствора за счёт ионов Cu²⁺. Научное объяснение: Схема процесса: Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-15-seg-3","startSeconds":145,"endSeconds":240,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. Scientific context: Reaction summary: Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓ теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. Научное объяснение: Схема процесса: Cu (s) + 2AgNO₃ (aq) → Cu(NO₃)₂ (aq, blue) + 2Ag (s, sparkling needles)↓. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('alkali-metals-sodium-in-water','{"id":"exp-16","slug":"alkali-metals-sodium-in-water","topicId":"metals","durationSeconds":185,"safetyLevel":"observe","youtubeVideo":"https://www.youtube.com/watch?v=dmcfsEEogxs","chemicalEquation":"2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑","illustration":"peroxide-foam","title":{"en":"Sodium in Water","ky":"Натрийдин суу менен реакциясы","ru":"Реакция натрия с водой"},"shortDescription":{"en":"Observe why a pea-sized piece of sodium melts into a silvery sphere, skitters across water propelled by H₂ gas, and trails pink phenolphthalein.","ky":"Натрийдин суу үстүндө күмүш шарчага айланып, H₂ газынын эсебинен жылып, фенолфталеинди мала кызылга боёшун байкаңыз.","ru":"Наблюдайте, как натрий плавится в серебристый шарик, стремительно бегает по воде и окрашивает фенолфталеин в малиновый цвет."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Reactivity of Alkali Metals: Sodium with Water & Phenolphthalein and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Metals & Reactivity.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["«Щелочтуу металлдардын активдүүлүгү: Натрийдин суу менен реакциясы» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Металлдар» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте «Активность щелочных металлов: реакция натрия с водой» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Металлы и активность».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Observe why a pea-sized piece of sodium melts into a silvery sphere, skitters across water propelled by H₂ gas, and trails pink phenolphthalein.","Reaction summary: 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Натрийдин суу үстүндө күмүш шарчага айланып, H₂ газынын эсебинен жылып, фенолфталеинди мала кызылга боёшун байкаңыз.","Процесстин негизги теңдемеси: 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Наблюдайте, как натрий плавится в серебристый шарик, стремительно бегает по воде и окрашивает фенолфталеин в малиновый цвет.","Схема процесса: 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Observe why a pea-sized piece of sodium melts into a silvery sphere, skitters across water propelled by H₂ gas, and trails pink phenolphthalein.","ky":"Натрийдин суу үстүндө күмүш шарчага айланып, H₂ газынын эсебинен жылып, фенолфталеинди мала кызылга боёшун байкаңыз.","ru":"Наблюдайте, как натрий плавится в серебристый шарик, стремительно бегает по воде и окрашивает фенолфталеин в малиновый цвет."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑.","ky":"2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑ теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Reactivity of Alkali Metals: Sodium with Water & Phenolphthalein\"?","ky":"«Щелочтуу металлдардын активдүүлүгү: Натрийдин суу менен реакциясы» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Активность щелочных металлов: реакция натрия с водой»?"},"conceptTag":"metals","options":[{"id":"a","text":{"en":"2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑","ky":"2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑","ru":"2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"Reactivity of Alkali Metals: Sodium with Water & Phenolphthalein\"?","ky":"«Щелочтуу металлдардын активдүүлүгү: Натрийдин суу менен реакциясы» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Активность щелочных металлов: реакция натрия с водой»?"},"conceptTag":"metals","options":[{"id":"a","text":{"en":"Observe why a pea-sized piece of sodium melts into a silvery sphere, skitters across water propelled by H₂ gas, and trails pink phenolphthalein.","ky":"Натрийдин суу үстүндө күмүш шарчага айланып, H₂ газынын эсебинен жылып, фенолфталеинди мала кызылга боёшун байкаңыз.","ru":"Наблюдайте, как натрий плавится в серебристый шарик, стремительно бегает по воде и окрашивает фенолфталеин в малиновый цвет."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-16-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Observe why a pea-sized piece of sodium melts into a silvery sphere, skitters across water propelled by H₂ gas, and trails pink phenolphthalein.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Натрийдин суу үстүндө күмүш шарчага айланып, H₂ газынын эсебинен жылып, фенолфталеинди мала кызылга боёшун байкаңыз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Наблюдайте, как натрий плавится в серебристый шарик, стремительно бегает по воде и окрашивает фенолфталеин в малиновый цвет."}},{"id":"exp-16-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Observe why a pea-sized piece of sodium melts into a silvery sphere, skitters across water propelled by H₂ gas, and trails pink phenolphthalein. Scientific context: Reaction summary: 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Натрийдин суу үстүндө күмүш шарчага айланып, H₂ газынын эсебинен жылып, фенолфталеинди мала кызылга боёшун байкаңыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Наблюдайте, как натрий плавится в серебристый шарик, стремительно бегает по воде и окрашивает фенолфталеин в малиновый цвет. Научное объяснение: Схема процесса: 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-16-seg-3","startSeconds":145,"endSeconds":185,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. Scientific context: Reaction summary: 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑ теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. Научное объяснение: Схема процесса: 2Na (s) + 2H₂O (l) → 2NaOH (aq) + H₂ (g)↑. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('supersaturated-sodium-acetate-hot-ice','{"id":"exp-17","slug":"supersaturated-sodium-acetate-hot-ice","topicId":"solutions","durationSeconds":210,"safetyLevel":"student_lab","youtubeVideo":"https://www.youtube.com/watch?v=7HDf2pE7mF0","chemicalEquation":"CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat","illustration":"crystal-lattice","title":{"en":"Hot Ice Crystallization","ky":"«Ысык муз» кристаллдашуусу","ru":"Кристаллизация «Горячего льда»"},"shortDescription":{"en":"Touch a single seed crystal to a clear, supercooled sodium acetate solution and watch needle crystals radiate outward while releasing warmth.","ky":"Тунук эритмеге бир кристалл тийгизгенде ийне сымал кристаллдар жылуулук бөлүп чыгаруу менен кантип тараларын көрүңүз.","ru":"Прикоснитесь кристаллом-затравкой к пересыщенному раствору и наблюдайте стремительный экзотермический рост кристаллов."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in ''Hot Ice'': Instant Crystallization of Supersaturated Sodium Acetate and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Crystals & Solutions.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["««Ысык муз»: Өтө каныккан натрий ацетатынын көз ирмемде кристаллдашуусу» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Кристаллдар жана эритмелер» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте ««Горячий лёд»: мгновенная кристаллизация пересыщенного ацетата натрия» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Кристаллы и растворы».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Touch a single seed crystal to a clear, supercooled sodium acetate solution and watch needle crystals radiate outward while releasing warmth.","Reaction summary: CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Тунук эритмеге бир кристалл тийгизгенде ийне сымал кристаллдар жылуулук бөлүп чыгаруу менен кантип тараларын көрүңүз.","Процесстин негизги теңдемеси: CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Прикоснитесь кристаллом-затравкой к пересыщенному раствору и наблюдайте стремительный экзотермический рост кристаллов.","Схема процесса: CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Touch a single seed crystal to a clear, supercooled sodium acetate solution and watch needle crystals radiate outward while releasing warmth.","ky":"Тунук эритмеге бир кристалл тийгизгенде ийне сымал кристаллдар жылуулук бөлүп чыгаруу менен кантип тараларын көрүңүз.","ru":"Прикоснитесь кристаллом-затравкой к пересыщенному раствору и наблюдайте стремительный экзотермический рост кристаллов."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat.","ky":"CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"''Hot Ice'': Instant Crystallization of Supersaturated Sodium Acetate\"?","ky":"««Ысык муз»: Өтө каныккан натрий ацетатынын көз ирмемде кристаллдашуусу» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте ««Горячий лёд»: мгновенная кристаллизация пересыщенного ацетата натрия»?"},"conceptTag":"solutions","options":[{"id":"a","text":{"en":"CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat","ky":"CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat","ru":"CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"''Hot Ice'': Instant Crystallization of Supersaturated Sodium Acetate\"?","ky":"««Ысык муз»: Өтө каныккан натрий ацетатынын көз ирмемде кристаллдашуусу» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте ««Горячий лёд»: мгновенная кристаллизация пересыщенного ацетата натрия»?"},"conceptTag":"solutions","options":[{"id":"a","text":{"en":"Touch a single seed crystal to a clear, supercooled sodium acetate solution and watch needle crystals radiate outward while releasing warmth.","ky":"Тунук эритмеге бир кристалл тийгизгенде ийне сымал кристаллдар жылуулук бөлүп чыгаруу менен кантип тараларын көрүңүз.","ru":"Прикоснитесь кристаллом-затравкой к пересыщенному раствору и наблюдайте стремительный экзотермический рост кристаллов."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-17-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Touch a single seed crystal to a clear, supercooled sodium acetate solution and watch needle crystals radiate outward while releasing warmth.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Тунук эритмеге бир кристалл тийгизгенде ийне сымал кристаллдар жылуулук бөлүп чыгаруу менен кантип тараларын көрүңүз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Прикоснитесь кристаллом-затравкой к пересыщенному раствору и наблюдайте стремительный экзотермический рост кристаллов."}},{"id":"exp-17-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Touch a single seed crystal to a clear, supercooled sodium acetate solution and watch needle crystals radiate outward while releasing warmth. Scientific context: Reaction summary: CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Тунук эритмеге бир кристалл тийгизгенде ийне сымал кристаллдар жылуулук бөлүп чыгаруу менен кантип тараларын көрүңүз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Прикоснитесь кристаллом-затравкой к пересыщенному раствору и наблюдайте стремительный экзотермический рост кристаллов. Научное объяснение: Схема процесса: CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-17-seg-3","startSeconds":145,"endSeconds":210,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. Scientific context: Reaction summary: CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. Научное объяснение: Схема процесса: CH₃COONa (aq, supersaturated) + 3H₂O —[seed crystal]→ CH₃COONa·3H₂O (s) + heat. Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('growing-copper-sulfate-single-crystals','{"id":"exp-18","slug":"growing-copper-sulfate-single-crystals","topicId":"solutions","durationSeconds":225,"safetyLevel":"student_lab","youtubeVideo":"https://www.youtube.com/watch?v=kK42f2b0B4Y","chemicalEquation":"Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal)","illustration":"crystal-lattice","title":{"en":"Copper Sulfate Crystals","ky":"Жез купоросунун кристаллдары","ru":"Кристаллы медного купороса"},"shortDescription":{"en":"Prepare a saturated solution, suspend a seed crystal, and understand how slow evaporation produces geometric triclinic crystal facets.","ky":"Каныккан эритме даярдап, жай буулантуу аркылуу геометриялык кырлары так болгон көк кристалл өстүрүңүз.","ru":"Приготовьте насыщенный раствор и проследите, как медленное испарение формирует правильные грани кристалла."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Growing Triclinic Copper(II) Sulfate Pentahydrate Crystals and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Crystals & Solutions.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["«Жез купоросунун (CuSO₄·5H₂O) чоң көк кристаллдарын өстүрүү» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Кристаллдар жана эритмелер» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте «Выращивание монокристаллов медного купороса (CuSO₄·5H₂O)» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Кристаллы и растворы».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation","Graduated pipette / spatula","Safety goggles, lab coat & gloves"],"ky":["Лабораториялык пробиркалар жана стакандар","Теңдемеде көрсөтүлгөн негизги реактивдер","Өлчөөчү пипетка же шпатель","Коргоочу көз айнек, халат жана кол кап"],"ru":["Лабораторные пробирки и химические стаканы","Реактивы согласно уравнению реакции","Мерная пипетка и шпатель","Защитные очки, халат и перчатки"]},"safetyNotes":{"en":["Always wear splash-proof safety goggles and follow your chemistry teacher''s instructions.","Dispose of reaction mixtures in designated laboratory waste containers rather than household sinks."],"ky":["Тажрыйба учурунда сөзсүз коргоочу көз айнек тагынып, химия мугалиминин көрсөтмөлөрүн так аткарыңыз.","Иштетилген эритмелерди атайын калдык идишке чогултуңуз."],"ru":["Обязательно используйте защитные очки и выполняйте работу только под руководством учителя химии.","Собирайте отработанные растворы в маркированные ёмкости для лабораторных отходов."]},"scientificExplanation":{"en":["Prepare a saturated solution, suspend a seed crystal, and understand how slow evaporation produces geometric triclinic crystal facets.","Reaction summary: Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level."],"ky":["Каныккан эритме даярдап, жай буулантуу аркылуу геометриялык кырлары так болгон көк кристалл өстүрүңүз.","Процесстин негизги теңдемеси: Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот."],"ru":["Приготовьте насыщенный раствор и проследите, как медленное испарение формирует правильные грани кристалла.","Схема процесса: Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."]},"steps":[{"timeSeconds":15,"title":{"en":"Apparatus & reagent setup","ky":"Шаймандарды жана реактивдерди даярдоо","ru":"Подготовка приборов и реактивов"},"detail":{"en":"Inspect clean glassware, verify labels, and measure initial quantities carefully.","ky":"Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз.","ru":"Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ."}},{"timeSeconds":70,"title":{"en":"Initiate reaction & observe key change","ky":"Реакцияны баштоо жана негизги белгини байкоо","ru":"Проведение опыта и наблюдение эффекта"},"detail":{"en":"Prepare a saturated solution, suspend a seed crystal, and understand how slow evaporation produces geometric triclinic crystal facets.","ky":"Каныккан эритме даярдап, жай буулантуу аркылуу геометриялык кырлары так болгон көк кристалл өстүрүңүз.","ru":"Приготовьте насыщенный раствор и проследите, как медленное испарение формирует правильные грани кристалла."}},{"timeSeconds":145,"title":{"en":"Analyze product & record conclusion","ky":"Жыйынтыкты талдоо","ru":"Анализ продуктов и формулировка вывода"},"detail":{"en":"Verify the products predicted by Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal).","ky":"Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal) теңдемеси боюнча пайда болгон заттарды талдайбыз.","ru":"Сопоставляем наблюдения с уравнением Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal)."}}],"quiz":[{"id":"q1","prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Growing Triclinic Copper(II) Sulfate Pentahydrate Crystals\"?","ky":"«Жез купоросунун (CuSO₄·5H₂O) чоң көк кристаллдарын өстүрүү» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Выращивание монокристаллов медного купороса (CuSO₄·5H₂O)»?"},"conceptTag":"solutions","options":[{"id":"a","text":{"en":"Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal)","ky":"Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal)","ru":"Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal)"}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."}}]},{"id":"q2","prompt":{"en":"What is the key observable outcome verified in \"Growing Triclinic Copper(II) Sulfate Pentahydrate Crystals\"?","ky":"«Жез купоросунун (CuSO₄·5H₂O) чоң көк кристаллдарын өстүрүү» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Выращивание монокристаллов медного купороса (CuSO₄·5H₂O)»?"},"conceptTag":"solutions","options":[{"id":"a","text":{"en":"Prepare a saturated solution, suspend a seed crystal, and understand how slow evaporation produces geometric triclinic crystal facets.","ky":"Каныккан эритме даярдап, жай буулантуу аркылуу геометриялык кырлары так болгон көк кристалл өстүрүңүз.","ru":"Приготовьте насыщенный раствор и проследите, как медленное испарение формирует правильные грани кристалла."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."}}]}],"transcriptSegments":[{"id":"exp-18-seg-1","startSeconds":0,"endSeconds":70,"text":{"en":"[Stage 1: Apparatus & reagent setup] Inspect clean glassware, verify labels, and measure initial quantities carefully. Scientific context: Prepare a saturated solution, suspend a seed crystal, and understand how slow evaporation produces geometric triclinic crystal facets.","ky":"[1-баскыч: Шаймандарды жана реактивдерди даярдоо] Идиштердин тазалыгын жана реактивдердин этикеткаларын текшерип, баштапкы көлөмдү ченейбиз. Илимий түшүндүрмө: Каныккан эритме даярдап, жай буулантуу аркылуу геометриялык кырлары так болгон көк кристалл өстүрүңүз.","ru":"[Этап 1: Подготовка приборов и реактивов] Проверяем чистоту посуды, маркировку склянок и отмеряем исходные порции веществ. Научное объяснение: Приготовьте насыщенный раствор и проследите, как медленное испарение формирует правильные грани кристалла."}},{"id":"exp-18-seg-2","startSeconds":70,"endSeconds":145,"text":{"en":"[Stage 2: Initiate reaction & observe key change] Prepare a saturated solution, suspend a seed crystal, and understand how slow evaporation produces geometric triclinic crystal facets. Scientific context: Reaction summary: Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[2-баскыч: Реакцияны баштоо жана негизги белгини байкоо] Каныккан эритме даярдап, жай буулантуу аркылуу геометриялык кырлары так болгон көк кристалл өстүрүңүз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 2: Проведение опыта и наблюдение эффекта] Приготовьте насыщенный раствор и проследите, как медленное испарение формирует правильные грани кристалла. Научное объяснение: Схема процесса: Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}},{"id":"exp-18-seg-3","startSeconds":145,"endSeconds":225,"text":{"en":"[Stage 3: Analyze product & record conclusion] Verify the products predicted by Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). Scientific context: Reaction summary: Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). By watching the rate of change, color shift, phase change, or temperature shift, we can directly verify conservation of mass and charge at the molecular level.","ky":"[3-баскыч: Жыйынтыкты талдоо] Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal) теңдемеси боюнча пайда болгон заттарды талдайбыз. Илимий түшүндүрмө: Процесстин негизги теңдемеси: Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). Өңдүн, агрегаттык абалдын же температуранын өзгөрүшү аркылуу молекулярдык деңгээлдеги кубулушту так көрүүгө болот.","ru":"[Этап 3: Анализ продуктов и формулировка вывода] Сопоставляем наблюдения с уравнением Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). Научное объяснение: Схема процесса: Cu²⁺ (aq) + SO₄²⁻ (aq) + 5H₂O (l) ⇌ CuSO₄·5H₂O (s, triclinic blue crystal). Наблюдая изменение окраски, агрегатного состояния или температуры, мы связываем видимые признаки реакции с перестройкой частиц."}}]}'::jsonb,'published');
insert into public.experiment_publications(slug,data,status) values ('solubility-potassium-nitrate-temperature','{"id":"exp-19","slug":"solubility-potassium-nitrate-temperature","topicId":"solutions","durationSeconds":240,"safetyLevel":"student_lab","youtubeVideo":"https://www.youtube.com/watch?v=kK42f2b0B4Y","chemicalEquation":"KNO₃ (s) + ΔH_soln ⇌ K⁺ (aq) + NO₃⁻ (aq)","illustration":"crystal-lattice","title":{"en":"Solubility of Potassium Nitrate","ky":"Калий нитратынын эригичтиги","ru":"Растворимость нитрата калия"},"shortDescription":{"en":"Measure crystallization temperatures at different concentrations to plot a real solubility curve and see why KNO₃ precipitates on cooling.","ky":"Ар кандай температурада кристаллдардын түшүшүн байкап, эригичтик ийри сызыгын түзүүнү үйрөнүңүз.","ru":"Определите температуру начала кристаллизации и постройте кривую растворимости соли в воде."},"featured":false,"objectives":{"en":["Observe the visual macroscopic changes in Effect of Temperature on the Solubility of Potassium Nitrate (KNO₃) and connect them to the balanced chemical equation.","Explain the particle-level mechanism within Crystals & Solutions.","Follow proper laboratory safety protocols and identify the required glassware and reagents."],"ky":["«Калий нитратынын (KNO₃) эригичтигине температуранын таасири» тажрыйбасындагы визуалдык белгилерди байкап, аларды реакциянын теңдемеси менен байланыштыруу.","«Кристаллдар жана эритмелер» темасынын негизинде кубулуштун молекулярдык маңызын түшүндүрүү.","Лабораториялык коопсуздук эрежелерин жана колдонулган шаймандарды билүү."],"ru":["Проследить макроскопические признаки в опыте «Зависимость растворимости нитрата калия (KNO₃) от температуры» и сопоставить их с уравнением процесса.","Объяснить механизм явления в рамках темы «Кристаллы и растворы».","Соблюдать правила техники безопасности при работе с лабораторной посудой и реактивами."]},"materials":{"en":["Borosilicate test tubes & beakers","Primary reagents shown in equation",